import * as THREE from '/static/vendor/three/three.module.js';
import { OrbitControls } from '/static/vendor/three/OrbitControls.js';
// (municipality modules loaded on demand via dynamic import)

const container = document.getElementById('three-canvas');



// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0xa7d1f1);

//NUEVO
const FOV     = 45.0;
const PLAT_CZ = 0.805;  // centro Z de la plataforma: (5.11 + -3.50) / 2

function calcH() {
  const w = container.clientWidth  || window.innerWidth;
  const h = container.clientHeight || window.innerHeight;
  if (!w || !h) return 15;
  const aspect = w / h;
  const tanHalfFov = Math.tan(FOV * Math.PI / 360);
  const hForDepth  = (8.61 * 1.10) / (2 * tanHalfFov);           // cubre Z
  const hForWidth  = (14.4 * 1.10) / (2 * tanHalfFov * aspect);  // cubre X
  const result = Math.max(hForDepth, hForWidth);
  return isFinite(result) ? result : 15;
}

const camera = new THREE.PerspectiveCamera(
  FOV,
  (container.clientWidth || window.innerWidth) / (container.clientHeight || window.innerHeight),
  0.1,
  100.0
);
camera.position.set(0, calcH(), PLAT_CZ - 0.001);
camera.lookAt(0, 0, PLAT_CZ);

// ── Renderer ──────────────────────────────────────────────────────────────
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(container.clientWidth, container.clientHeight);
renderer.setPixelRatio(window.devicePixelRatio);
container.appendChild(renderer.domElement);

// ── Controls — SIEMPRE después del renderer ───────────────────────────────
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.enableRotate  = false;
controls.target.set(0, 0, PLAT_CZ);
controls.update();


