m66g.userData={"name": "Somiedo", "capital": "Pola de Somiedo", "population": 1045, "altitude_m": 720, "comarca": "Oviedo", "area_km2": 291.38, "density": 3.6, "fun_fact": "Parque Natural de Somiedo, primera Reserva de la Biosfera de Asturias (2000). Principal refugio del oso pardo cant\u00e1brico, con 40-50% de la poblaci\u00f3n total. Sus teitos (caba\u00f1as con techo de escoba) son arquitectura vern\u00e1cula \u00fanica. Los lagos de Saliencia son de origen glaciar. Gastronom\u00eda basada en el cerdo y la huerta."};
scene.add(m66g);markers.push(m66g);
