// Raycaster interaction
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();
const card = document.getElementById('info-card');
const hint = document.getElementById('hint');
const closePlatformBtn = document.getElementById('btn-close-platform');
let selectedMarker = null;

let selectedPolygon = null;
let polyAnimTarget = null;
let isPolyAnimating = false;  // true while polygon is mid-animation (blocks canvas clicks)
const activeModules = [];   // modules with update(t) from dynamic imports
let polyCenterWeight = 0;
let cameraAnimTarget = null;

// Camera rest position (cenital/drone)
const CAM_REST_POS = new THREE.Vector3(0, 12, -0.001);
const CAM_REST_TARGET = new THREE.Vector3(0, 0, 0);
// Camera isometric position
const CAM_ISO_POS = new THREE.Vector3(6, 6, -6);
const CAM_ISO_TARGET = new THREE.Vector3(0, 0.75, 0);

function resetBuildings(poly) {
    if (poly && poly.userData.buildings) {
        poly.userData.buildings.forEach(b => {
            b.mesh.visible = false;
            b.mesh.rotation.x = b.flatRotX;
        });

    }
    if (poly.userData.buildings) {
    poly.userData.buildings.forEach(b => {
        // Esto mantiene los iconos pegados a la plataforma mientras sube
        b.mesh.position.y = poly.position.y + b.heightOffset;
    })
}
}

function animatePolygon(poly) {
    const now = performance.now();
    isPolyAnimating = true;

    if (selectedPolygon === poly) {
        // --- COLAPSAR: El concejo vuelve al suelo ---
        polyAnimTarget = { 
            poly: poly, 
            targetY: 0, 
            targetScale: 1.0,
            targetCenterW: 0, 
            expanding: false,
            startY: poly.position.y, 
            startS: poly.scale.x,
            startW: polyCenterWeight,
            targetThickness: 1, 
            startThickness: poly.scale.y,
            startTime: now 
        };

        cameraAnimTarget = { 
            startPos: camera.position.clone(),
            endPos: CAM_REST_POS.clone(),
            startTarget: controls.target.clone(),
            endTarget: CAM_REST_TARGET.clone(),
            startTime: now, 
            duration: 500, 
            expanding: false 
        };
        
        // ⭐ OCULTAR ICONOS al empezar a bajar
        resetBuildings(poly);

        controls.enabled = false;
        selectedPolygon = null;
        if (closePlatformBtn) closePlatformBtn.style.display = 'none';

    } else {
        // --- SNAP-RESET: Si había otro concejo abierto, lo cerramos de golpe ---
        if (selectedPolygon) {
            resetBuildings(selectedPolygon);
            selectedPolygon.position.set(0, 0, 0);
            selectedPolygon.scale.set(1, 1, 1);
            selectedPolygon.renderOrder = 0;
            selectedPolygon.material.color.setHex(selectedPolygon.userData.originalColor);
        }

        polyCenterWeight = 0;
        selectedPolygon = poly;
        poly.renderOrder = 10;
        if (closePlatformBtn) closePlatformBtn.style.display = 'flex';

        // Guardar color y poner color de "plataforma"
        poly.userData.originalColor = poly.material.color.getHex();
        poly.material.color.setHex(0xb4cfcb);

        card.style.display = 'none';
        selectedMarker = null;
        _clearSearchHighlight();
        if (_searchInput) _searchInput.value = '';
        if (_searchDrop)  { _searchDrop.innerHTML = ''; _searchDrop.classList.remove('open'); }

        // --- EXPANDIR: El concejo sube ---
        polyAnimTarget = { 
            poly: poly, 
            targetY: 0.75,
            targetScale: poly.userData.fillScale,
            targetCenterW: 1, 
            expanding: true,
            startY: 0, 
            startS: 1, 
            startW: 0,
            targetThickness: 1.05, 
            startThickness: 1,
            startTime: now 
        };

        cameraAnimTarget = { 
            startPos: camera.position.clone(),
            endPos: CAM_ISO_POS.clone(),
            startTarget: controls.target.clone(),
            endTarget: CAM_ISO_TARGET.clone(),
            startTime: now, 
            duration: 800, 
            expanding: true 
        };

        // ⭐ MOSTRAR ICONOS al empezar a subir
        if (poly.userData.buildings) {
            poly.userData.buildings.forEach(b => {
                b.mesh.visible = true;
            });
        }

        // Cargar módulo del municipio (primera vez)
        _loadMunicipalityModule(poly);

        controls.enabled = false;
    }
}

// ── Dynamic import helpers ────────────────────────────────────────────────────
function _municipioSlug(name) {
    return (name || '').toLowerCase()
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .replace(/\s+/g, '_');
}

async function _loadMunicipalityModule(poly) {
    if (poly.userData.moduleLoaded) return;
    poly.userData.moduleLoaded = true;
    const slug = _municipioSlug(poly.userData.name);
    if (!slug) return;
    try {
        const mod = await import(`/static/js/${slug}/index.js?v=1773992808`);
        await mod.load(scene, poly);
        // Mostrar los nuevos items si la plataforma ya está subida
        if (selectedPolygon === poly && poly.userData.buildings) {
            poly.userData.buildings.forEach(b => { b.mesh.visible = true; });
        }
        if (typeof mod.update === 'function') activeModules.push(mod);
    } catch(e) { /* municipio sin módulo específico, normal */ }
}

function _preloadMunicipalityModule(poly) {
    if (poly.userData.modulePreloaded) return;
    poly.userData.modulePreloaded = true;
    const slug = _municipioSlug(poly.userData.name);
    if (slug) import(`/static/js/${slug}/index.js?v=1773992808`).catch(() => {});
}
// ─────────────────────────────────────────────────────────────────────────────

if (closePlatformBtn) {
    closePlatformBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (selectedPolygon) {
            cerrarModal();                     // cierra el modal si está abierto
            _hideBuildingCard();               // cierra tarjeta de edificio si está abierta
            window.closeMarketCard && window.closeMarketCard();  // cierra tarjeta mercado
            animatePolygon(selectedPolygon);   // colapsa la plataforma
        }
    });
}

renderer.domElement.addEventListener('click', (e) => {
    if (isPolyAnimating) return;  // ignore clicks during polygon transition
    const rect = renderer.domElement.getBoundingClientRect();
    mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(mouse, camera);

    // ⭐ DETECCIÓN DE CARTELES DE LA PLAZA + buildings individuales
    if (selectedPolygon && selectedPolygon.userData.buildings) {
        const iconMeshes = selectedPolygon.userData.buildings.map(b => b.mesh);
        const buildingsHits = raycaster.intersectObjects(iconMeshes, true);
        if (buildingsHits.length > 0) {
            const muni = selectedPolygon.userData.name;
            // Iterar todos los hits por orden de distancia
            for (const _hit of buildingsHits) {
                let current = _hit.object;
                while (current) {
                    // 0. Disco mercado waypoint
                    if (current.userData.tipo === 'mercado_waypoint') {
                        const cfg = current.userData.marketConfig;
                        const plazaEntry = allPlazas.find(pe => pe.polygon === selectedPolygon);
                        if (plazaEntry && !isPolyAnimating) {
                            const state = plazaEntry.plaza.userData.plazaState;
                            _hideBuildingCard();
                            state.activeMarket = cfg;
                            state.activeBuilding = null;
                            state.activeSign = null;
                            state.returningToCenter = false;
                            state.targetPosLocal.set(cfg.offsetX, 0.68 * state.S, cfg.offsetZ);
                            state.isMoving = true;
                        }
                        return;
                    }
                    // 1. Disco waypoint (hitbox del círculo de edificio)
                    if (current.userData.waypointId) {
                        const wd = current.userData.waypointData;
                        const plazaEntry = allPlazas.find(pe => pe.polygon === selectedPolygon);
                        if (plazaEntry && !isPolyAnimating) {
                            const state = plazaEntry.plaza.userData.plazaState;
                            _hideBuildingCard();
                            state.activeBuilding = wd;
                            state.activeSign = null;
                            state.returningToCenter = false;
                            state.targetPosLocal.set(wd.offsetX, 0.68 * state.S, wd.offsetZ);
                            state.isMoving = true;
                        }
                        return;
                    }
                    // 2. Cartel de la plaza
                    if (current.userData.tipo) {
                        const tipo = current.userData.tipo;
                        if (tipo.startsWith('plaza_') && tipo !== 'plaza') {
                            const signEntry = PLAZA_SIGN_DATA.find(sd => sd.tipo === tipo);
                            if (signEntry && !isPolyAnimating) {
                                const plazaEntry = allPlazas.find(pe => pe.polygon === selectedPolygon);
                                if (plazaEntry) {
                                    const state = plazaEntry.plaza.userData.plazaState;
                                    const _S = state.S;
                                    state.activeSign = { tipo, modal: signEntry.modal, angle: signEntry.angle };
                                    state.targetPosLocal.set(
                                        Math.cos(signEntry.angle) * 3.6 * _S,
                                        0.68 * _S,
                                        Math.sin(signEntry.angle) * 3.6 * _S
                                    );
                                    state.isMoving = true;
                                    state.returningToCenter = false;
                                }
                            }
                            return;
                        }
                        break; // tipo 'plaza' u otro → parar traversal para este hit
                    }
                    current = current.parent;
                }
            }
        }
    }
   
    //makers — bloqueados mientras hay plataforma expandida
    if (!selectedPolygon) {
    const hits = raycaster.intersectObjects(markers);
    if (hits.length > 0) {
        const d = hits[0].object.userData;
        document.getElementById('card-name').textContent = d.name;
        document.getElementById('card-capital').textContent = 'Capital: ' + d.capital;
        document.getElementById('card-pop').textContent = d.population.toLocaleString('es-ES') + ' hab.';
        document.getElementById('card-alt').textContent = d.altitude_m + ' m';
        document.getElementById('card-area').textContent = d.area_km2 + ' km\u00B2';
        document.getElementById('card-density').textContent = d.density + ' hab/km\u00B2';
        document.getElementById('card-comarca').textContent = 'Comarca: ' + d.comarca;
        document.getElementById('card-fact').textContent = d.fun_fact;
        card.style.display = 'block';
        if (hint) hint.style.display = 'none';
        selectedMarker = hits[0].object;
        return;
    }
    } // end !selectedPolygon guard
    // Polygon is expanded: block all canvas clicks (only X button closes it)
    if (selectedPolygon) return;
    const polyHits = raycaster.intersectObjects(polygons);
    if (polyHits.length > 0) {
        animatePolygon(polyHits[0].object);
    } else {
        card.style.display = 'none';
        selectedMarker = null;
    }
});

renderer.domElement.addEventListener('mousemove', (e) => {
    const rect = renderer.domElement.getBoundingClientRect();
    mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(mouse, camera);
    // When polygon is expanded, pointer only over the platform
    if (selectedPolygon) {
        const polyHover = raycaster.intersectObjects([selectedPolygon]);
        renderer.domElement.style.cursor = polyHover.length > 0 ? 'pointer' : 'default';
        return;
    }
    const markerHits = raycaster.intersectObjects(markers);
    if (markerHits.length > 0) {
        renderer.domElement.style.cursor = 'pointer';
        return;
    }
    const polyHits = raycaster.intersectObjects(polygons);
    renderer.domElement.style.cursor = polyHits.length > 0 ? 'pointer' : 'default';
    // Precargar módulo del municipio al hacer hover
    if (polyHits.length > 0) _preloadMunicipalityModule(polyHits[0].object);
});



