// ─── Mercado waypoint por municipio ──────────────────────────────────────────
const MARKET_WAYPOINTS = {
    'Gijón': { offsetX: 0.23, offsetZ: -0.05, color: 0xFFD700 },
};

// ─── Textura canvas para tablero del cartel ───────────────────────────────────
function _makeSignTexture(label, accentColor) {
    const cv = document.createElement('canvas');
    cv.width = 400; cv.height = 140;
    const ctx = cv.getContext('2d');
    // Fondo madera
    ctx.fillStyle = '#b07d52';
    ctx.fillRect(0, 0, 400, 140);
    // Veta de madera
    ctx.strokeStyle = 'rgba(0,0,0,0.07)';
    ctx.lineWidth = 2;
    for (let i = 0; i < 9; i++) {
        ctx.beginPath(); ctx.moveTo(0, i * 18); ctx.lineTo(400, i * 18 + 5); ctx.stroke();
    }
    // Franja de color abajo
    ctx.fillStyle = accentColor;
    ctx.fillRect(0, 96, 400, 44);
    // Línea divisoria
    ctx.strokeStyle = 'rgba(255,255,255,0.25)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(14, 94); ctx.lineTo(386, 94); ctx.stroke();
    // Texto negro más grande
    ctx.font = 'bold 38px Arial, sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.shadowColor = 'rgba(255,255,255,0.4)'; ctx.shadowBlur = 3; ctx.shadowOffsetY = 0;
    ctx.fillStyle = '#111111';
    ctx.fillText(label, 200, 44);
    // Línea decorativa
    ctx.shadowBlur = 0;
    ctx.fillStyle = 'rgba(0,0,0,0.08)';
    ctx.fillRect(14, 74, 372, 3);
    return new THREE.CanvasTexture(cv);
}

// ─── Cartel de madera ─────────────────────────────────────────────────────────
function _makePlazaSign(data, S) {
    const group = new THREE.Group();
    // Post ligeramente cónico (más alto)
    const post = new THREE.Mesh(
        new THREE.CylinderGeometry(0.08 * S, 0.12 * S, 3.5 * S, 8),
        new THREE.MeshLambertMaterial({ color: 0x8b5e3c })
    );
    post.position.y = 1.75 * S;
    group.add(post);
    // Marco de madera oscura (más ancho)
    const frame = new THREE.Mesh(
        new THREE.BoxGeometry(2.9 * S, 1.35 * S, 0.06 * S),
        new THREE.MeshLambertMaterial({ color: 0x7a5230 })
    );
    frame.position.set(0, 3.65 * S, -0.02 * S);
    group.add(frame);
    // Tablero con textura canvas (más grande)
    const board = new THREE.Mesh(
        new THREE.BoxGeometry(2.75 * S, 1.2 * S, 0.12 * S),
        new THREE.MeshLambertMaterial({ map: _makeSignTexture(data.label, data.colorHex) })
    );
    board.position.y = 3.65 * S;
    group.add(board);
    // 4 clavos en esquinas
    [[1.2, 0.5], [-1.2, 0.5], [1.2, -0.5], [-1.2, -0.5]].forEach(([x, y]) => {
        const nail = new THREE.Mesh(
            new THREE.SphereGeometry(0.055 * S, 8, 8),
            new THREE.MeshPhongMaterial({ color: 0x888888, shininess: 80 })
        );
        nail.position.set(x * S, (3.65 + y) * S, 0.07 * S);
        group.add(nail);
    });
    // Hitbox invisible para raycaster
    const hit = new THREE.Mesh(
        new THREE.BoxGeometry(3.0 * S, 4.5 * S, 0.9 * S),
        new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })
    );
    hit.position.y = 2.2 * S;
    hit.userData.tipo = data.tipo;
    group.add(hit);
    // Posición en arco (radio reducido con la plataforma más pequeña)
    group.position.set(Math.cos(data.angle) * 5.0 * S, 0.3 * S, Math.sin(data.angle) * 5.0 * S);
    group.lookAt(0, group.position.y, 0);
    return group;
}

// ─── Iconos 3D para burbujas ──────────────────────────────────────────────────
function _makeIconMesh(type, color, S) {
    const g = new THREE.Group();
    const mat = new THREE.MeshLambertMaterial({ color });
    if (type === 'ocio') {
        // Cubo de palomitas
        const bucket = new THREE.Mesh(new THREE.CylinderGeometry(0.19 * S, 0.14 * S, 0.32 * S, 8), mat);
        bucket.position.y = -0.05 * S; g.add(bucket);
        const sm = new THREE.MeshLambertMaterial({ color: 0xe63946 });
        for (let i = 0; i < 3; i++) {
            const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.045 * S, 0.33 * S, 0.42 * S), sm);
            stripe.position.set((-0.14 + i * 0.14) * S, -0.05 * S, 0); stripe.rotation.y = Math.PI / 2; g.add(stripe);
        }
        [[-0.1, 0.18, 0], [0.1, 0.2, 0.05], [0, 0.24, -0.05], [0.12, 0.16, -0.08], [-0.05, 0.14, 0.1]].forEach(([x, y, z]) => {
            const puff = new THREE.Mesh(new THREE.SphereGeometry(0.1 * S, 8, 8), new THREE.MeshLambertMaterial({ color: 0xfffbe6 }));
            puff.position.set(x * S, y * S, z * S); g.add(puff);
        });
    } else if (type === 'restaurantes') {
        // Tenedor y cuchillo
        const m = new THREE.MeshPhongMaterial({ color: 0xd4d4d4, shininess: 80 });
        const fork = new THREE.Mesh(new THREE.CylinderGeometry(0.026 * S, 0.026 * S, 0.44 * S, 6), m);
        fork.position.set(-0.15 * S, 0, 0); g.add(fork);
        for (let i = 0; i < 4; i++) {
            const t = new THREE.Mesh(new THREE.CylinderGeometry(0.014 * S, 0.014 * S, 0.15 * S, 4), m);
            t.position.set((-0.22 + i * 0.05) * S, 0.29 * S, 0); g.add(t);
        }
        const knife = new THREE.Mesh(new THREE.CylinderGeometry(0.026 * S, 0.026 * S, 0.44 * S, 6), m);
        knife.position.set(0.15 * S, 0, 0); g.add(knife);
        const blade = new THREE.Mesh(new THREE.BoxGeometry(0.07 * S, 0.18 * S, 0.025 * S), m);
        blade.position.set(0.15 * S, 0.27 * S, 0); g.add(blade);
    } else if (type === 'tiendas') {
        // Bolsa de compras
        const bag = new THREE.Mesh(new THREE.BoxGeometry(0.34 * S, 0.36 * S, 0.14 * S), mat);
        bag.position.y = -0.06 * S; g.add(bag);
        const curve = new THREE.QuadraticBezierCurve3(
            new THREE.Vector3(-0.11 * S, 0.13 * S, 0),
            new THREE.Vector3(0, 0.31 * S, 0),
            new THREE.Vector3(0.11 * S, 0.13 * S, 0)
        );
        g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(curve.getPoints(16)), new THREE.LineBasicMaterial({ color: 0x6a4020 })));
        const win = new THREE.Mesh(new THREE.BoxGeometry(0.18 * S, 0.12 * S, 0.15 * S), new THREE.MeshLambertMaterial({ color: 0xffffff, transparent: true, opacity: 0.35 }));
        win.position.set(0, -0.02 * S, 0); g.add(win);
    }
    return g;
}

// ─── Burbuja flotante sobre cartel ────────────────────────────────────────────
function _makeBubble(data, signPos, S) {
    const g = new THREE.Group();
    // Esfera translúcida
    g.add(new THREE.Mesh(
        new THREE.SphereGeometry(0.7 * S, 32, 32),
        new THREE.MeshPhongMaterial({ color: 0xbbddff, transparent: true, opacity: 0.2, side: THREE.DoubleSide, shininess: 130, specular: new THREE.Color(0xffffff) })
    ));
    // Anillo de color
    const ring = new THREE.Mesh(
        new THREE.TorusGeometry(0.5 * S, 0.04 * S, 8, 36),
        new THREE.MeshBasicMaterial({ color: data.color, transparent: true, opacity: 0.6 })
    );
    ring.rotation.x = Math.PI / 2; g.add(ring);
    // Icono 3D
    g.add(_makeIconMesh(data.modal, data.color, S));
    g.position.set(signPos.x, 13.8 * S, signPos.z);
    return g;
}

// ─── Personaje — Traje Asturiano ─────────────────────────────────────────────
function _makePlazaCharacter(S) {
    const g = new THREE.Group();

    // ── MATERIALS ──
    const skinMat   = new THREE.MeshPhongMaterial({ color: 0xffcba4, shininess: 50 });
    const hairMat   = new THREE.MeshPhongMaterial({ color: 0x3d2b1f, shininess: 22 });
    const eyeWMat   = new THREE.MeshPhongMaterial({ color: 0xffffff, shininess: 80 });
    const eyeMat    = new THREE.MeshPhongMaterial({ color: 0x080808, shininess: 100 });
    const shineMat  = new THREE.MeshBasicMaterial({ color: 0xffffff });
    const shirtMat  = new THREE.MeshPhongMaterial({ color: 0xf0f0eb, shininess: 28 });
    const vestMat   = new THREE.MeshPhongMaterial({ color: 0x111111, shininess: 22 });
    const vestRedMat= new THREE.MeshPhongMaterial({ color: 0xaa0e0e, shininess: 18 });
    const fajaMat   = new THREE.MeshPhongMaterial({ color: 0xcc1010, shininess: 18 });
    const pantMat   = new THREE.MeshPhongMaterial({ color: 0x0d0d0d, shininess: 18 });
    const sockMat   = new THREE.MeshPhongMaterial({ color: 0xe8e8e8, shininess: 12 });
    const buttonMat = new THREE.MeshPhongMaterial({ color: 0xb87820, shininess: 130 });

    // ── CABEZA: dos hemisferios ──
    const cutPhi = Math.PI * 0.38;
    const headSkin = new THREE.Mesh(
        new THREE.SphereGeometry(0.40*S, 36, 36, 0, Math.PI*2, cutPhi, Math.PI-cutPhi),
        new THREE.MeshPhongMaterial({ color: 0xffcba4, shininess: 45 })
    );
    headSkin.position.y = 1.76*S; g.add(headSkin);
    const headHair = new THREE.Mesh(
        new THREE.SphereGeometry(0.40*S, 36, 36, 0, Math.PI*2, 0, cutPhi),
        new THREE.MeshPhongMaterial({ color: 0x3d2b1f, shininess: 25 })
    );
    headHair.position.y = 1.76*S; g.add(headHair);

    // Rizos
    function addCurl(theta, phi) {
        const R = 0.41*S;
        const sz = (0.040 + Math.random()*0.016) * S;
        const x = R*Math.sin(theta)*Math.cos(phi);
        const y = R*Math.cos(theta);
        const z = R*Math.sin(theta)*Math.sin(phi);
        const curl = new THREE.Mesh(new THREE.TorusGeometry(sz, sz*0.4, 7, 11), hairMat);
        curl.position.set(x, 1.76*S + y, z);
        const out = new THREE.Vector3(x, y, z).normalize();
        curl.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), out);
        curl.rotateOnAxis(out, phi*1.3 + theta*2.1);
        g.add(curl);
    }
    [[0.05,0],[0.07,2.2],[0.09,4.5]].forEach(([t,p]) => addCurl(t,p));
    for (let i=0; i<7;  i++) addCurl(0.28, (i/7)*Math.PI*2);
    for (let i=0; i<10; i++) addCurl(0.52, (i/10)*Math.PI*2+0.3);
    for (let i=0; i<13; i++) addCurl(0.76, (i/13)*Math.PI*2+0.15);
    for (let i=0; i<15; i++) addCurl(1.00, (i/15)*Math.PI*2+0.5);
    [[0.38,1.0],[0.38,3.2],[0.62,0.5],[0.62,2.0],[0.62,3.8],[0.85,1.2],[0.85,3.5],[0.46,4.0],[0.70,1.7]].forEach(([t,p]) => addCurl(t,p));

    // ── MONTERA PICONA — cúpula baja + picos cápsula 3D ──
    (function makeMontera() {
        const negro = new THREE.MeshPhongMaterial({ color: 0x0e0e0e, shininess: 35 });
        const rojo  = new THREE.MeshPhongMaterial({ color: 0x8b0a0a, shininess: 25, side: THREE.DoubleSide });
        const cinta = new THREE.MeshPhongMaterial({ color: 0xaa0a0a, shininess: 55 });

        const hat = new THREE.Group();
        // Más bajo: la cúpula debe tocar/cubrir el pelo (bajar de 2.095 a 1.98)
        hat.position.set(0, 1.98*S, 0.01*S);
        hat.rotation.z =  0.07;
        hat.rotation.x = -0.04;

        // Casquete: cúpula ancha que baja hasta cubrir la cabeza (phi 0.62*PI)
        const dome = new THREE.Mesh(
            new THREE.SphereGeometry(0.455*S, 32, 20, 0, Math.PI*2, 0, Math.PI*0.62), negro);
        dome.scale.y = 0.60;
        hat.add(dome);

        // Forro interior rojo
        const domeIn = new THREE.Mesh(
            new THREE.SphereGeometry(0.435*S, 26, 16, 0, Math.PI*2, 0, Math.PI*0.58), rojo);
        domeIn.scale.y = 0.58;
        hat.add(domeIn);

        // helper: prisma triangular con base arqueada — cara ancha mira ±X, canto fino al frente
        // curve: cuánto sube el centro de la base para seguir la curva del casquete
        function makeVela(hw_z, height, tx, curve) {
            const geo = new THREE.BufferGeometry();
            // 8 vértices: izq/centro/der base + ápice  × cara +X y cara -X
            const p = new Float32Array([
                 tx, 0,       -hw_z,  // 0 base-izq   +X
                 tx, curve,    0,     // 1 base-centro +X (arqueado)
                 tx, 0,        hw_z,  // 2 base-der   +X
                 tx, height,   0,     // 3 ápice       +X
                -tx, 0,       -hw_z,  // 4 base-izq   -X
                -tx, curve,    0,     // 5 base-centro -X (arqueado)
                -tx, 0,        hw_z,  // 6 base-der   -X
                -tx, height,   0,     // 7 ápice       -X
            ]);
            geo.setAttribute('position', new THREE.BufferAttribute(p, 3));
            geo.setIndex([
                0,3,1,  1,3,2,       // cara triangular +X (2 triángulos)
                4,5,7,  5,6,7,       // cara triangular -X
                0,4,7,  0,7,3,       // canto Z=-hw_z (tira fina delantera)
                2,3,7,  2,7,6,       // canto Z=+hw_z (tira fina trasera)
                0,1,5,  0,5,4,       // base arqueada mitad izq
                1,2,6,  1,6,5,       // base arqueada mitad der
            ]);
            geo.computeVertexNormals();
            return geo;
        }
        const negroV = new THREE.MeshPhongMaterial({ color: 0x0e0e0e, shininess: 35, side: THREE.DoubleSide });

        // PICO GRANDE — vela izquierda, base arqueada y ajustada al radio del casquete
        // hw_z=0.25*S: radio efectivo del casco en x=−0.36*S es ≈0.278*S → margen limpio
        // curve=0.12*S: arco pronunciado para que el perfil siga la cúpula
        const bigP = new THREE.Mesh(makeVela(0.25*S, 0.52*S, 0.025*S, 0.12*S), negroV);
        bigP.position.set(-0.36*S, 0.08*S, 0);
        bigP.rotation.z = 0.12;
        hat.add(bigP);

        // PICO PEQUEÑO — vela derecha, base arqueada, más baja
        const smallP = new THREE.Mesh(makeVela(0.26*S, 0.37*S, 0.020*S, 0.04*S), negroV);
        smallP.position.set(0.34*S, 0.03*S, 0);
        smallP.rotation.z = -0.10;
        hat.add(smallP);

        // Ribete rojo al borde del casquete (ajustado a nueva posición)
        const ribete = new THREE.Mesh(new THREE.TorusGeometry(0.443*S, 0.016*S, 8, 40), cinta);
        ribete.rotation.x = Math.PI/2;
        ribete.position.y = -0.068*S;
        hat.add(ribete);

        g.add(hat);
    })();

    // ── OJOS ──
    [-0.15, 0.15].forEach(x => {
        const ew = new THREE.Mesh(new THREE.SphereGeometry(0.1*S,14,14), eyeWMat);
        ew.position.set(x*S, 1.76*S, 0.36*S); g.add(ew);
        const ep = new THREE.Mesh(new THREE.SphereGeometry(0.06*S,12,12), eyeMat);
        ep.position.set(x*S, 1.75*S, 0.43*S); g.add(ep);
        const sh = new THREE.Mesh(new THREE.SphereGeometry(0.022*S,6,6), shineMat);
        sh.position.set((x+0.03)*S, 1.78*S, 0.46*S); g.add(sh);
    });
    [-1, 1].forEach(s => {
        const b = new THREE.Mesh(new THREE.SphereGeometry(0.08*S,10,10),
            new THREE.MeshBasicMaterial({ color: 0xffaaaa, transparent: true, opacity: 0.4 }));
        b.position.set(s*0.27*S, 1.66*S, 0.33*S); g.add(b);
    });

    // ── NARIZ ──
    const nose = new THREE.Mesh(new THREE.SphereGeometry(0.068*S,14,12),
        new THREE.MeshPhongMaterial({ color: 0xf0b090, shininess: 40 }));
    nose.scale.set(1.0, 0.72, 0.85); nose.position.set(0, 1.69*S, 0.41*S); g.add(nose);
    [-1, 1].forEach(s => {
        const no = new THREE.Mesh(new THREE.SphereGeometry(0.020*S,8,8),
            new THREE.MeshPhongMaterial({ color: 0xd08060, shininess: 20 }));
        no.scale.set(1, 0.5, 1); no.position.set(s*0.032*S, 1.672*S, 0.454*S); g.add(no);
    });

    // ── BOCA ANIMABLE (CanvasTexture) ──
    const MOUTH_W = 256, MOUTH_H = 128;
    const mouthCanvas = document.createElement('canvas');
    mouthCanvas.width = MOUTH_W; mouthCanvas.height = MOUTH_H;
    const mouthCtx = mouthCanvas.getContext('2d');
    const mouthTex = new THREE.CanvasTexture(mouthCanvas);
    const mouthPlane = new THREE.Mesh(
        new THREE.PlaneGeometry(0.22*S, 0.11*S),
        new THREE.MeshBasicMaterial({ map: mouthTex, transparent: true, depthWrite: false })
    );
    mouthPlane.position.set(0, 1.605*S, 0.408*S);
    mouthPlane.rotation.x = -0.18;
    g.add(mouthPlane);

    const mouthState = { mode: 'smile', openAmt: 0.0, phase: 0.0, talking: false, talkSpeed: 8 };

    function drawMouth() {
        const ctx = mouthCtx;
        const cx = MOUTH_W/2, cy = MOUTH_H/2;
        ctx.clearRect(0, 0, MOUTH_W, MOUTH_H);
        const open = mouthState.openAmt, mode = mouthState.mode;
        const lipC = '#c0504a', innC = '#6b1c1c', tthC = '#f5f5f0';
        ctx.lineCap = 'round'; ctx.lineJoin = 'round';
        if (mode === 'surprised') {
            ctx.beginPath(); ctx.ellipse(cx,cy+8,36,28,0,0,Math.PI*2);
            ctx.fillStyle=innC; ctx.fill(); ctx.strokeStyle=lipC; ctx.lineWidth=7; ctx.stroke();
            ctx.beginPath(); ctx.ellipse(cx,cy+2,28,16,0,0,Math.PI*2); ctx.fillStyle=tthC; ctx.fill();
        } else if (mode === 'talk' || open > 0.05) {
            const aperture = Math.max(open, mode==='talk' ? 0.35+Math.sin(mouthState.phase*Math.PI*2)*0.30 : 0);
            const oy = aperture * 30;
            ctx.beginPath(); ctx.moveTo(cx-52,cy);
            ctx.bezierCurveTo(cx-26,cy-14,cx+26,cy-14,cx+52,cy);
            ctx.bezierCurveTo(cx+26,cy-6,cx-26,cy-6,cx-52,cy);
            ctx.fillStyle=lipC; ctx.fill();
            if (oy > 3) {
                ctx.beginPath(); ctx.ellipse(cx,cy+oy*0.4,44,oy*0.85,0,0,Math.PI*2);
                ctx.fillStyle=innC; ctx.fill();
                if (oy > 10) {
                    ctx.beginPath(); ctx.ellipse(cx,cy+2,36,Math.min(oy*0.4,12),0,0,Math.PI);
                    ctx.fillStyle=tthC; ctx.fill();
                }
            }
            ctx.beginPath(); ctx.moveTo(cx-52,cy);
            ctx.bezierCurveTo(cx-26,cy+8+oy,cx+26,cy+8+oy,cx+52,cy);
            ctx.bezierCurveTo(cx+26,cy+18+oy,cx-26,cy+18+oy,cx-52,cy);
            ctx.fillStyle=lipC; ctx.fill();
        } else if (mode === 'smile') {
            ctx.beginPath(); ctx.moveTo(cx-52,cy-2);
            ctx.bezierCurveTo(cx-20,cy-20,cx+20,cy-20,cx+52,cy-2);
            ctx.bezierCurveTo(cx+24,cy+22,cx-24,cy+22,cx-52,cy-2);
            ctx.fillStyle=lipC; ctx.fill();
            ctx.beginPath(); ctx.moveTo(cx-50,cy-2);
            ctx.bezierCurveTo(cx-20,cy+14,cx+20,cy+14,cx+50,cy-2);
            ctx.strokeStyle='#993030'; ctx.lineWidth=3; ctx.stroke();
            [-52,52].forEach(ox => { ctx.beginPath(); ctx.arc(cx+ox,cy-2,5,0,Math.PI*2); ctx.fillStyle='#b04040'; ctx.fill(); });
        } else {
            ctx.beginPath(); ctx.moveTo(cx-44,cy+4);
            ctx.bezierCurveTo(cx-15,cy-4,cx+15,cy-4,cx+44,cy+4);
            ctx.strokeStyle=lipC; ctx.lineWidth=8; ctx.stroke();
        }
        mouthTex.needsUpdate = true;
    }
    drawMouth();

    // ── CUELLO + COLLAR ──
    const neck = new THREE.Mesh(new THREE.SphereGeometry(0.17*S,16,16), skinMat);
    neck.scale.set(0.9,0.75,0.9); neck.position.y = 1.44*S; g.add(neck);
    const collar = new THREE.Mesh(new THREE.CylinderGeometry(0.20*S,0.22*S,0.14*S,16), shirtMat);
    collar.position.y = 1.41*S; g.add(collar);

    // ── CAMISA (cuerpo) ──
    const shirtBody = new THREE.Mesh(new THREE.SphereGeometry(0.47*S,28,28), shirtMat);
    shirtBody.scale.set(1.0,1.12,0.88); shirtBody.position.y = 1.06*S; g.add(shirtBody);

    // ── CHALECO NEGRO ──
    // Envolvente lateral+espalda (270°)
    const vestWrapTop = new THREE.Mesh(
        new THREE.CylinderGeometry(0.495*S,0.475*S,0.52*S,32,1,true, Math.PI*0.18,Math.PI*1.64), vestMat);
    vestWrapTop.position.y = 1.18*S; g.add(vestWrapTop);
    const vestWrapBot = new THREE.Mesh(
        new THREE.CylinderGeometry(0.495*S,0.475*S,0.32*S,32,1,true, Math.PI*0.18,Math.PI*1.64), vestMat);
    vestWrapBot.position.y = 0.82*S; g.add(vestWrapBot);
    // Forro rojo espalda
    const vestRedBack = new THREE.Mesh(
        new THREE.CylinderGeometry(0.497*S,0.478*S,0.28*S,28,1,true, Math.PI*0.40,Math.PI*1.20), vestRedMat);
    vestRedBack.position.y = 0.84*S; g.add(vestRedBack);
    // Hombros chaleco
    [-1,1].forEach(s => {
        const shT = new THREE.Mesh(new THREE.BoxGeometry(0.28*S,0.11*S,0.52*S), vestMat);
        shT.position.set(s*0.37*S, 1.38*S, -0.02*S); g.add(shT);
        const shS = new THREE.Mesh(new THREE.BoxGeometry(0.10*S,0.22*S,0.50*S), vestMat);
        shS.position.set(s*0.46*S, 1.26*S, -0.02*S); g.add(shS);
    });
    // Paneles frontales + base
    const fPL = new THREE.Mesh(new THREE.BoxGeometry(0.30*S,0.74*S,0.10*S), vestMat);
    fPL.position.set(-0.235*S,1.08*S,0.36*S); fPL.rotation.y =  0.12; g.add(fPL);
    const fPR = new THREE.Mesh(new THREE.BoxGeometry(0.30*S,0.74*S,0.10*S), vestMat);
    fPR.position.set( 0.235*S,1.08*S,0.36*S); fPR.rotation.y = -0.12; g.add(fPR);
    const fBot = new THREE.Mesh(new THREE.BoxGeometry(0.54*S,0.08*S,0.10*S), vestMat);
    fBot.position.set(0, 0.70*S, 0.37*S); g.add(fBot);
    // Botones dorados (5)
    [1.36,1.22,1.08,0.94,0.82].forEach(y => {
        const btn = new THREE.Mesh(new THREE.CylinderGeometry(0.027*S,0.027*S,0.042*S,10), buttonMat);
        btn.rotation.x = Math.PI/2; btn.position.set(0.02*S, y*S, 0.43*S); g.add(btn);
    });
    // Cordoncillo trasero
    for (let i=0; i<5; i++) {
        const cord = new THREE.Mesh(new THREE.SphereGeometry(0.015*S,6,6), buttonMat);
        cord.position.set(i%2===0?-0.022*S:0.022*S, (1.26-i*0.062)*S, -0.50*S); g.add(cord);
    }

    // ── FAJA ROJA ──
    const faja = new THREE.Mesh(new THREE.CylinderGeometry(0.44*S,0.42*S,0.25*S,30), fajaMat);
    faja.position.y = 0.71*S; g.add(faja);
    for (let i=0; i<10; i++) {
        const len = (0.14+(i%3)*0.04)*S;
        const fr = new THREE.Mesh(new THREE.CylinderGeometry(0.010*S,0.006*S,len,5), fajaMat);
        fr.position.set((0.28+i*0.024)*S, 0.60*S-len*0.5, (0.20-i*0.035)*S);
        fr.rotation.z=0.06+i*0.035; fr.rotation.x=-0.08; g.add(fr);
    }

    // ── HOMBROS camisa (blancos bajo chaleco) ──
    [-1,1].forEach(s => {
        const sh = new THREE.Mesh(new THREE.SphereGeometry(0.215*S,16,16), shirtMat);
        sh.position.set(s*0.48*S, 1.24*S, 0.02*S); g.add(sh);
    });

    // ── BRAZOS (mangas blancas) ──
    let armPivotL, armPivotR;
    [-1,1].forEach(s => {
        const ap = new THREE.Group();
        ap.position.set(s*0.48*S, 1.24*S, 0.02*S); g.add(ap);
        const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.138*S,0.108*S,0.48*S,14), shirtMat);
        arm.position.set(s*0.065*S,-0.27*S,0.04*S); arm.rotation.z=s*0.20; ap.add(arm);
        const cuff = new THREE.Mesh(new THREE.CylinderGeometry(0.120*S,0.120*S,0.09*S,14), shirtMat);
        cuff.position.set(s*0.11*S,-0.54*S,0.04*S); ap.add(cuff);
        const hand = new THREE.Mesh(new THREE.SphereGeometry(0.115*S,14,14),
            new THREE.MeshPhongMaterial({ color: 0xffcba4, shininess: 50 }));
        hand.position.set(s*0.12*S,-0.65*S,0.04*S); ap.add(hand);
        if (s===-1) { armPivotL=ap; } else { armPivotR=ap; }
    });

    // ── MADREÑAS (cuerpo flat/boxy como GLB) ──
    function makeMadreña(side) {
        const mg  = new THREE.Group();
        const mat = new THREE.MeshPhongMaterial({ color: 0x0c0c0c, shininess: 75 });
        const tMat= new THREE.MeshPhongMaterial({ color: 0x1a1a1a, shininess: 45 });
        // Cuerpo principal: caja plana
        const body = new THREE.Mesh(new THREE.BoxGeometry(0.32*S,0.12*S,0.50*S), mat);
        body.position.set(0, 0.06*S, 0.02*S); mg.add(body);
        // Punta delantera elevada
        const toe = new THREE.Mesh(new THREE.BoxGeometry(0.24*S,0.10*S,0.18*S), mat);
        toe.position.set(0, 0.10*S, 0.30*S); toe.rotation.x=-0.30; mg.add(toe);
        // Apertura superior (torus oval)
        const opening = new THREE.Mesh(new THREE.TorusGeometry(0.095*S,0.019*S,7,22),
            new THREE.MeshPhongMaterial({ color: 0x040404, shininess: 8 }));
        opening.scale.set(1.05,0.50,1.0); opening.position.set(0,0.158*S,0.055*S);
        opening.rotation.x=-0.22; mg.add(opening);
        // 3 tacos
        [{ x:0.000,z:-0.155,h:0.105,r:0.042 },
         { x:-0.065,z:0.130,h:0.092,r:0.036 },
         { x:0.065,z:0.130,h:0.092,r:0.036 }].forEach(({x,z,h,r}) => {
            const pata = new THREE.Mesh(new THREE.CylinderGeometry(r*0.70*S,r*S,h*S,10), tMat);
            pata.position.set(x*S,(0.014-h*0.5)*S,z*S); mg.add(pata);
        });
        if (side===1) mg.scale.x=-1;
        return mg;
    }

    // ── PIERNAS (calzón negro + calcetines + madreñas) ──
    let legPivotL, legPivotR;
    [-1,1].forEach(s => {
        const lp = new THREE.Group();
        lp.position.set(s*0.19*S, 0.68*S, 0); g.add(lp);
        // Muslo
        lp.add(new THREE.Mesh(new THREE.SphereGeometry(0.225*S,16,16), pantMat));
        // Calzón
        const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.158*S,0.130*S,0.44*S,14), pantMat);
        leg.position.y=-0.26*S; lp.add(leg);
        // Dobladillo
        const hem = new THREE.Mesh(new THREE.CylinderGeometry(0.150*S,0.150*S,0.055*S,14), pantMat);
        hem.position.y=-0.48*S; lp.add(hem);
        // Botones bajo calzón
        for (let i=0; i<3; i++) {
            const a=(-0.4+i*0.4)*s;
            const btn = new THREE.Mesh(new THREE.CylinderGeometry(0.018*S,0.018*S,0.032*S,8), buttonMat);
            btn.rotation.z=Math.PI/2; btn.position.set(s*0.13*Math.cos(a)*S,-0.47*S,(0.13*Math.sin(a)+0.05)*S); lp.add(btn);
        }
        // Calcetín blanco
        const sock = new THREE.Mesh(new THREE.CylinderGeometry(0.135*S,0.122*S,0.38*S,16), sockMat);
        sock.position.y=-0.68*S; lp.add(sock);
        const sockT = new THREE.Mesh(new THREE.CylinderGeometry(0.148*S,0.138*S,0.065*S,14), sockMat);
        sockT.position.y=-0.51*S; lp.add(sockT);
        // Patrón calado
        for (let row=0; row<5; row++) for (let col=0; col<12; col++) {
            if ((row+col)%2===0) continue;
            const a2=(col/12)*Math.PI*2;
            const dot = new THREE.Mesh(new THREE.SphereGeometry(0.012*S,4,4),
                new THREE.MeshBasicMaterial({ color:0xcccccc,transparent:true,opacity:0.5 }));
            dot.position.set(Math.sin(a2)*0.141*S,(-0.56-row*0.07)*S,Math.cos(a2)*0.141*S); lp.add(dot);
        }
        // Madreña
        const mad = makeMadreña(s);
        mad.position.set(0,-0.905*S,0.02*S); lp.add(mad);
        if (s===-1) { legPivotL=lp; } else { legPivotR=lp; }
    });

    g.position.set(0, 0.68*S, 0);
    return { group: g, userData: { armPivotL, armPivotR, legPivotL, legPivotR, drawMouth, mouthState } };
}

// ─── Plataforma completa ──────────────────────────────────────────────────────
function _makePlaza(S) {
    const plazaGroup = new THREE.Group();

    // Disco principal
    const disc = new THREE.Mesh(
        new THREE.CylinderGeometry(6*S, 6.3*S, 0.5*S, 64),
        new THREE.MeshLambertMaterial({ color: 0xd4c5a9 })
    );
    plazaGroup.add(disc);

    // Borde torus
    const ring = new THREE.Mesh(
        new THREE.TorusGeometry(6.15*S, 0.15*S, 8, 64),
        new THREE.MeshLambertMaterial({ color: 0xb8a882 })
    );
    ring.rotation.x = Math.PI/2; ring.position.y = 0.15*S; plazaGroup.add(ring);

    // 6 círculos decorativos
    for (let i=0; i<6; i++) {
        const a = (i/6)*Math.PI*2;
        const circ = new THREE.Mesh(
            new THREE.CylinderGeometry(0.4*S,0.4*S,0.05*S,16),
            new THREE.MeshLambertMaterial({ color: 0xc4b898 })
        );
        circ.position.set(Math.cos(a)*4.2*S, 0.27*S, Math.sin(a)*4.2*S); plazaGroup.add(circ);
    }

    // Emblema central hexagonal
    const emb = new THREE.Mesh(
        new THREE.CylinderGeometry(1.0*S,1.0*S,0.06*S,6),
        new THREE.MeshLambertMaterial({ color: 0xe8d8b0 })
    );
    emb.position.y = 0.27*S; plazaGroup.add(emb);

    // Puntos de camino hacia los carteles
    PLAZA_SIGN_DATA.forEach(data => {
        const dot = new THREE.Mesh(
            new THREE.CylinderGeometry(0.15*S,0.15*S,0.02*S,16),
            new THREE.MeshBasicMaterial({ color: data.color })
        );
        dot.position.set(Math.cos(data.angle)*5.0*0.72*S, 0.27*S, Math.sin(data.angle)*5.0*0.72*S);
        plazaGroup.add(dot);
    });

    // Carteles + burbujas
    const bubblesLocal = [];
    PLAZA_SIGN_DATA.forEach(data => {
        const sign = _makePlazaSign(data, S);
        sign.userData.tipo = data.tipo;
        plazaGroup.add(sign);
        const bubble = _makeBubble(data, sign.position, S);
        plazaGroup.add(bubble);
        bubblesLocal.push(bubble);
    });

    // Personaje
    const charResult = _makePlazaCharacter(S);
    charResult.group.rotation.y = Math.PI;  // mira al norte
    plazaGroup.add(charResult.group);

    // Pool de partículas de polvo (regreso veloz)
    const dustGroup = new THREE.Group();
    plazaGroup.add(dustGroup);
    const _dustColors = [0xffffff, 0xf5f0e8, 0xc8b89a];
    const dustParticles = Array.from({length: 16}, (_, i) => {
        const mesh = new THREE.Mesh(
            new THREE.SphereGeometry(0.35 * S, 5, 5),
            new THREE.MeshBasicMaterial({ color: _dustColors[i % _dustColors.length], transparent: true, opacity: 0 })
        );
        mesh.visible = false;
        dustGroup.add(mesh);
        return { mesh, life: 0, vx: 0, vz: 0 };
    });

    plazaGroup.userData.plazaState = {
        isMoving: false,
        returningToCenter: false,
        activeSign: null,
        activeBuilding: null,
        activeMarket: null,
        waypointMarkers: [],
        walkCycle: 0,
        charGroup: charResult.group,
        charParts: charResult.userData,
        targetPosLocal: new THREE.Vector3(0, 0.68*S, 0),
        dustParticles,
        dustGroup,
        S,
    };
    plazaGroup.userData.bubbles = bubblesLocal;
    plazaGroup.userData.tipo = 'plaza';
    plazaGroup.visible = false;
    return plazaGroup;
}

// ── Plaza del Monigote (scope:all) ─────────────────────────────────────────────
const allPlazas = [];
polygons.forEach(p => {
    const _plaza = _makePlaza(PLAZA_SCALE);
    scene.add(_plaza);
    if (!p.userData.buildings) p.userData.buildings = [];
    p.userData.buildings.push({ mesh: _plaza, offsetX: 0.0, offsetZ: -0.02, flatRotX: 0, heightOffset: 0.0, isPlaza: true });
    allPlazas.push({ plaza: _plaza, polygon: p });
});

// ─── Waypoint markers por municipio ─────────────────────────────────────────
allPlazas.forEach(({ plaza, polygon }) => {
    const wList = WAYPOINT_BUILDINGS[polygon.userData.name];
    if (!wList) return;
    const state = plaza.userData.plazaState;
    const S = state.S;
    const wMarkers = [];
    wList.forEach(wd => {
        const mGroup = new THREE.Group();
        // Disco idéntico a los puntos de camino de la plaza
        const disc = new THREE.Mesh(
            new THREE.CylinderGeometry(0.15 * S, 0.15 * S, 0.02 * S, 16),
            new THREE.MeshBasicMaterial({ color: wd.color })
        );
        disc.position.y = 0.27 * S;
        mGroup.add(disc);
        // Hitbox para click (cilindro generoso sobre el disco)
        const hit = new THREE.Mesh(
            new THREE.CylinderGeometry(0.5 * S, 0.5 * S, 0.5 * S, 12),
            new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })
        );
        hit.userData.waypointId = wd.id;
        hit.userData.waypointData = wd;
        hit.position.y = 0.3 * S;
        mGroup.add(hit);
        mGroup.position.set(wd.offsetX, 0, wd.offsetZ);
        plaza.add(mGroup);
        wMarkers.push({ group: mGroup, disc, data: wd });
    });
    state.waypointMarkers = wMarkers;
});

// ─── Mercado disc (disco dorado clickable) ────────────────────────────────────
allPlazas.forEach(({ plaza, polygon }) => {
    const mCfg = MARKET_WAYPOINTS[polygon.userData.name];
    if (!mCfg) return;
    const state = plaza.userData.plazaState;
    const S = state.S;
    const mGroup = new THREE.Group();
    // Disco dorado grande
    const disc = new THREE.Mesh(
        new THREE.CylinderGeometry(0.22 * S, 0.22 * S, 0.025 * S, 20),
        new THREE.MeshBasicMaterial({ color: mCfg.color })
    );
    disc.position.y = 0.27 * S;
    disc.visible = false;  // replaced by 3D mercado-market.js scene
    mGroup.add(disc);
    // Signo — ocultado, sustituido por escena 3D mercado-market.js
    const sign = new THREE.Mesh(
        new THREE.CylinderGeometry(0.08 * S, 0.08 * S, 0.12 * S, 8),
        new THREE.MeshBasicMaterial({ color: 0xcc8800 })
    );
    sign.visible = false;
    sign.position.y = 0.42 * S;
    mGroup.add(sign);
    // Hitbox invisible generoso
    const hit = new THREE.Mesh(
        new THREE.CylinderGeometry(0.55 * S, 0.55 * S, 0.6 * S, 12),
        new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })
    );
    hit.userData.tipo = 'mercado_waypoint';
    hit.userData.marketConfig = mCfg;
    hit.position.y = 0.35 * S;
    mGroup.add(hit);
    mGroup.position.set(mCfg.offsetX, 0, mCfg.offsetZ);
    plaza.add(mGroup);
});

// ─── Animación fiel al diseño ─────────────────────────────────────────────────
function _animatePlazaCharacter(state, delta, t, muniName, polygon) {
    const char  = state.charGroup;
    const parts = state.charParts;
    const S     = state.S;
    const { armPivotL, armPivotR, legPivotL, legPivotR } = parts;

    if (state.isMoving) {
        const dir  = new THREE.Vector3().subVectors(state.targetPosLocal, char.position);
        dir.y = 0; // ignora el rebote Y para detectar llegada solo en XZ
        const dist = dir.length();
        if (dist > 0.09 * S) {
            state.walkCycle += delta * (state.returningToCenter ? 22 : 13);
            dir.normalize();
            // Esquivar obstáculos: centro real de bounding box + diagonal como radio
            let sx = dir.x, sz = dir.z;
            if (polygon && polygon.userData.buildings) {
                const tx = state.targetPosLocal.x, tz = state.targetPosLocal.z;
                const arriveDamp = Math.min(1.0, dist / 0.12);
                polygon.userData.buildings.forEach(b => {
                    if (b.isPlaza) return; // skip plaza
                    // Calcular centro y radio reales desde bounding box (cacheado)
                    if (b._avoidR === undefined) {
                        const _box = new THREE.Box3().setFromObject(b.mesh);
                        const _bcen = _box.getCenter(new THREE.Vector3());
                        const _bsz  = _box.getSize(new THREE.Vector3());
                        const _fs   = Math.max(b.mesh.scale.x, 0.01);
                        // Centro del BB en espacio local de la plaza
                        b._avoidCX = (_bcen.x - (b.mesh.position.x - b.offsetX * _fs)) / _fs;
                        b._avoidCZ = (_bcen.z - (b.mesh.position.z - b.offsetZ * _fs)) / _fs;
                        // Radio = semidiagonal del footprint (cubre esquinas) + margen
                        const _hx = _bsz.x / (_fs * 2.0);
                        const _hz = _bsz.z / (_fs * 2.0);
                        b._avoidR = Math.sqrt(_hx * _hx + _hz * _hz) * 1.3 + 0.025;
                    }
                    const dx = char.position.x - b._avoidCX;
                    const dz = char.position.z - b._avoidCZ;
                    const od = Math.sqrt(dx * dx + dz * dz);
                    if (od < b._avoidR && od > 0.001) {
                        const str = Math.pow(1 - od / b._avoidR, 1.5) * 2.2 * arriveDamp;
                        sx += (dx / od) * str;
                        sz += (dz / od) * str;
                    }
                });
                const sl = Math.sqrt(sx * sx + sz * sz);
                if (sl > 0.001) { sx /= sl; sz /= sl; }
            }
            const speed = state.returningToCenter ? 28.0 : 8.0;
            const step = Math.min(speed * S * delta, dist);
            char.position.x += sx * step;
            char.position.z += sz * step;
            // Cara hacia destino
            char.rotation.y = Math.atan2(sx, sz);
            // Partículas de polvo al regresar
            if (state.returningToCenter && state.dustParticles) {
                for (let _e = 0; _e < 2; _e++) {
                    const fp = state.dustParticles.find(p => !p.mesh.visible);
                    if (fp) {
                        fp.mesh.visible = true;
                        fp.mesh.position.set(
                            char.position.x - sx * 0.3 * S + (Math.random() - 0.5) * 0.4 * S,
                            0.3 * S,
                            char.position.z - sz * 0.3 * S + (Math.random() - 0.5) * 0.4 * S
                        );
                        fp.mesh.scale.setScalar(1);
                        fp.mesh.material.opacity = 1.0;
                        fp.vx = (Math.random() - 0.5) * 4.0 * S;
                        fp.vz = (Math.random() - 0.5) * 4.0 * S;
                        fp.life = 1.0;
                    }
                }
            }
            // Walk swing
            const sw = Math.sin(state.walkCycle) * 0.5;
            if (armPivotL) armPivotL.rotation.x =  sw;
            if (armPivotR) armPivotR.rotation.x = -sw;
            if (legPivotL) legPivotL.rotation.x = -sw;
            if (legPivotR) legPivotR.rotation.x =  sw;
            // Boca: modo habla mientras camina
            if (parts.drawMouth && parts.mouthState) {
                parts.mouthState.phase += delta * parts.mouthState.talkSpeed;
                if (parts.mouthState.mode !== 'talk') { parts.mouthState.mode='talk'; parts.mouthState.talking=true; }
                parts.drawMouth();
            }
            // Bounce
            char.position.y = 0.68*S + Math.abs(Math.sin(state.walkCycle*2)) * 0.045*S;
        } else {
            // Llegó
            char.position.copy(state.targetPosLocal);
            if (armPivotL) armPivotL.rotation.x = 0;
            if (armPivotR) armPivotR.rotation.x = 0;
            if (legPivotL) legPivotL.rotation.x = 0;
            if (legPivotR) legPivotR.rotation.x = 0;
            state.isMoving = false;
            if (state.returningToCenter) {
                char.rotation.y = Math.PI;
                state.returningToCenter = false;
            } else if (state.activeSign) {
                // Cara hacia el cartel
                const signPos = new THREE.Vector3(Math.cos(state.activeSign.angle)*5.0*S, 0, Math.sin(state.activeSign.angle)*5.0*S);
                const toSign  = new THREE.Vector3().subVectors(signPos, char.position).normalize();
                char.rotation.y = Math.atan2(toSign.x, toSign.z);
                const modal = state.activeSign.modal;
                state.activeSign = null;
                setTimeout(() => abrirModal(muniName, modal), 400);
            } else if (state.activeBuilding) {
                // Monigote mira al edificio
                const bPos = new THREE.Vector3(state.activeBuilding.offsetX, 0, state.activeBuilding.offsetZ);
                const toB = new THREE.Vector3().subVectors(bPos, char.position).normalize();
                char.rotation.y = Math.atan2(toB.x, toB.z);
                const bData = state.activeBuilding;
                state.activeBuilding = null;
                setTimeout(() => _showBuildingCard(bData), 400);
            } else if (state.activeMarket) {
                // Monigote mira al disco mercado
                const mPos = new THREE.Vector3(state.activeMarket.offsetX, 0, state.activeMarket.offsetZ);
                const toM = new THREE.Vector3().subVectors(mPos, char.position).normalize();
                char.rotation.y = Math.atan2(toM.x, toM.z);
                const mData = state.activeMarket;
                state.activeMarket = null;
                setTimeout(() => _showMarketCard(muniName, mData), 400);
            }
            char.position.y = 0.68*S;
        }
    } else {
        // Idle: bobbing + brazos balanceo lateral (rotation.z)
        char.position.y = 0.68*S + Math.sin(t*1.5)*0.03*S;
        if (armPivotL) { armPivotL.rotation.z =  Math.sin(t*1.1)*0.12+0.1; armPivotL.rotation.x = 0; }
        if (armPivotR) { armPivotR.rotation.z = -Math.sin(t*1.1)*0.12-0.1; armPivotR.rotation.x = 0; }
        if (legPivotL) legPivotL.rotation.x = 0;
        if (legPivotR) legPivotR.rotation.x = 0;
        // Boca: sonrisa en idle
        if (parts.drawMouth && parts.mouthState && parts.mouthState.mode !== 'smile') {
            parts.mouthState.talking=false; parts.mouthState.mode='smile'; parts.drawMouth();
        }
    }
    // Actualizar partículas de polvo activas
    if (state.dustParticles) {
        state.dustParticles.forEach(p => {
            if (!p.mesh.visible) return;
            p.life -= 2.2 * delta;
            if (p.life <= 0) { p.mesh.visible = false; p.mesh.material.opacity = 0; return; }
            p.mesh.position.x += p.vx * delta;
            p.mesh.position.z += p.vz * delta;
            p.mesh.material.opacity = p.life;
            p.mesh.scale.setScalar(0.5 + p.life * 0.8);
        });
    }
}


// ── SHADERS DEL MAR ──────────────────────────────────────────────────────────

const oceanVertexShader = `
  uniform float uTime;
  varying vec2 vUv;
  varying float vElevation;

  void main() {
    vUv = uv;
    vec3 pos = position;

    // Capa 1: olas largas de fondo (mar abierto)
    float wave1 = sin(pos.x * 1.2 + uTime * 0.8) * cos(pos.y * 0.8 + uTime * 0.5) * 0.04;

    // Capa 2: olas medianas cruzadas
    float wave2 = sin(pos.x * 2.5 - uTime * 1.1 + 1.3) * sin(pos.y * 2.0 + uTime * 0.7) * 0.025;

    // Capa 3: rizos pequeños superficiales
    float wave3 = sin(pos.x * 5.0 + uTime * 2.2) * cos(pos.y * 4.5 - uTime * 1.8) * 0.01;

    // Capa 4: olas que rompen acercándose a la costa (sur del plano = Z negativo en el plano 2D)
    // uv.y = 0 → sur (costa), uv.y = 1 → norte (mar abierto)
    float coastFactor = 1.0 - vUv.y; // más intenso cerca de la costa
    float breakingWave = sin(pos.x * 3.0 + uTime * 1.5) * coastFactor * 0.03;

    vElevation = wave1 + wave2 + wave3 + breakingWave;
    pos.z += vElevation; // El plano está rotado, Z aquí es la altura en el mundo

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
  }
`;

const oceanFragmentShader = `
  uniform float uTime;
  uniform vec3 uDeepColor;
  uniform vec3 uShallowColor;
  uniform vec3 uFoamColor;
  varying vec2 vUv;
  varying float vElevation;

  // Ruido simple para espuma
  float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
  }
  float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(
      mix(hash(i), hash(i + vec2(1,0)), f.x),
      mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x),
      f.y
    );
  }

  void main() {
    // Color base: mezcla profundo/superficial según elevación
    float t = clamp((vElevation + 0.07) / 0.14, 0.0, 1.0);
    vec3 color = mix(uDeepColor, uShallowColor, t);

    // Espuma en crestas de olas
    float foamNoise = noise(vUv * 12.0 + uTime * 0.25);
    float foamMask = smoothstep(0.025, 0.07, vElevation) * (0.5 + foamNoise * 0.5);
    color = mix(color, uFoamColor, foamMask * 0.75);

    // Espuma extra cerca de la costa (borde sur del plano)
    float coastFoam = (1.0 - vUv.y) * noise(vUv * 20.0 + uTime * 0.5) * 0.4;
    color = mix(color, uFoamColor, coastFoam);

    // Brillo especular simulado en crestas
    color += pow(max(0.0, vElevation * 8.0), 2.5) * 0.15;

    // Fade suave en el borde norte (mar abierto se funde con el fondo)
    float fadeNorth = smoothstep(0.85, 1.0, vUv.y);
    float alpha = 0.82 - fadeNorth * 0.25;

    gl_FragColor = vec4(color, alpha);
  }
`;

// ── GEOMETRÍA DEL MAR ALINEADA CON EL LITORAL ────────────────────────────────

// Puntos del litoral asturiano: [world_x, world_z_costa]
// Definen el borde sur del océano / norte del terreno, siguiendo la costa real.
// Compartidos por createCoastAlignedOceanGeo y buildUnifiedPlatform.
const COAST_POINTS = [[-7.2, 0.4147], [-4.993, 0.4147], [-4.943, 0.4147], [-4.893, 0.4147], [-4.843, 0.4147], [-4.793, 0.4147], [-4.743, 0.3876], [-4.693, 0.3876], [-4.643, 0.3876], [-4.243, 0.4996], [-4.193, 0.4996], [-4.143, 0.4996], [-4.093, 0.5844], [-4.043, 0.598], [-3.993, 0.6421], [-3.943, 0.6421], [-3.893, 0.6421], [-3.843, 0.676], [-3.793, 0.676], [-3.743, 0.676], [-3.693, 0.676], [-3.643, 0.6489], [-3.593, 0.6489], [-3.543, 0.7677], [-3.493, 0.7677], [-3.443, 0.7677], [-3.393, 0.7677], [-3.343, 0.7677], [-3.293, 0.7643], [-3.243, 0.7643], [-3.193, 0.7643], [-3.143, 0.7643], [-3.093, 0.7677], [-3.043, 0.7677], [-2.993, 0.7677], [-2.943, 0.7677], [-2.893, 0.7677], [-2.793, 0.8966], [-2.743, 0.8966], [-2.693, 0.8966], [-2.643, 0.8966], [-2.593, 0.8966], [-2.543, 0.8559], [-2.493, 0.8559], [-2.443, 0.8559], [-2.393, 0.8457], [-2.343, 0.8457], [-2.293, 1.0765], [-2.243, 1.1274], [-2.193, 1.1274], [-2.143, 1.1274], [-2.093, 1.1647], [-2.043, 1.1647], [-1.993, 1.1647], [-1.943, 1.1647], [-1.893, 1.2054], [-1.843, 1.2054], [-1.793, 1.2054], [-1.743, 1.2903], [-1.693, 1.2903], [-1.643, 1.2903], [-1.593, 1.2903], [-1.543, 1.2903], [-1.443, 1.2428], [-1.393, 1.2428], [-1.343, 1.2869], [-1.293, 1.2869], [-1.243, 1.2869], [-1.193, 1.2869], [-1.143, 1.2869], [-1.093, 1.2699], [-1.043, 1.2699], [-0.993, 1.3208], [-0.943, 1.3208], [-0.893, 1.3208], [-0.843, 1.3208], [-0.793, 1.3208], [-0.743, 1.2869], [-0.693, 1.2869], [-0.643, 1.3887], [-0.593, 1.3887], [-0.543, 1.3887], [-0.493, 1.3887], [-0.443, 1.5821], [-0.393, 1.7213], [-0.343, 1.7213], [-0.293, 1.7213], [-0.243, 1.7213], [-0.193, 1.7722], [-0.143, 1.8672], [-0.093, 1.8672], [-0.043, 1.8672], [0.007, 1.8672], [0.057, 1.8672], [0.107, 1.8502], [0.157, 1.7009], [0.207, 1.7009], [0.257, 1.7009], [0.307, 1.7009], [0.357, 1.5686], [0.407, 1.5482], [0.457, 1.4701], [0.507, 1.5244], [0.557, 1.5244], [0.607, 1.5244], [0.657, 1.5244], [0.707, 1.5244], [0.757, 1.4464], [0.807, 1.4464], [0.857, 1.4464], [0.907, 1.4159], [0.957, 1.3717], [1.007, 1.4464], [1.057, 1.4464], [1.107, 1.4464], [1.157, 1.5075], [1.207, 1.538], [1.257, 1.538], [1.307, 1.538], [1.357, 1.5991], [1.407, 1.5991], [1.457, 1.5991], [1.507, 1.5991], [1.557, 1.5991], [1.607, 1.5041], [1.707, 1.4226], [1.757, 1.4226], [1.807, 1.4226], [1.857, 1.4226], [1.907, 1.4226], [1.957, 1.4226], [2.007, 1.4226], [2.057, 1.4057], [2.107, 1.4057], [2.157, 1.4057], [2.207, 1.5041], [2.257, 1.5041], [2.307, 1.5041], [2.357, 1.5041], [2.407, 1.5041], [2.457, 1.4328], [2.507, 1.4328], [2.557, 1.4328], [2.607, 1.4328], [2.657, 1.4328], [2.707, 1.5007], [2.757, 1.5007], [2.807, 1.5346], [2.857, 1.5346], [2.907, 1.5346], [2.957, 1.5346], [3.007, 1.5211], [3.057, 1.5211], [3.107, 1.5211], [3.157, 1.4735], [3.207, 1.4735], [3.257, 1.4735], [3.307, 1.5448], [3.357, 1.5448], [3.407, 1.5448], [3.457, 1.5448], [3.507, 1.5448], [3.557, 1.5007], [3.607, 1.5007], [3.657, 1.5686], [3.707, 1.5686], [3.757, 1.5686], [3.807, 1.5686], [3.857, 1.5346], [3.907, 1.5346], [3.957, 1.6025], [4.007, 1.6025], [4.057, 1.6025], [4.107, 1.6025], [4.157, 1.6025], [4.207, 1.5448], [4.257, 1.5414], [4.307, 1.5414], [4.357, 1.5414], [4.407, 1.5414], [4.457, 1.5414], [4.507, 1.4668], [7.2, 1.4668]].sort((a,b)=>a[0]-b[0]);

// Devuelve world_z de la costa en la posición world_x dada (interpolación lineal)
function zCoastAt(wx) {
  if (wx <= COAST_POINTS[0][0]) return COAST_POINTS[0][1];
  const last = COAST_POINTS[COAST_POINTS.length - 1];
  if (wx >= last[0]) return last[1];
  for (let i = 0; i < COAST_POINTS.length - 1; i++) {
    const [x0, z0] = COAST_POINTS[i];
    const [x1, z1] = COAST_POINTS[i + 1];
    if (wx >= x0 && wx <= x1) {
      const t = (wx - x0) / (x1 - x0);
      return z0 + t * (z1 - z0);
    }
  }
  return last[1];
}

function createCoastAlignedOceanGeo(segmentsX, segmentsZ) {
  // Relación entre coordenadas local y world (rotation.x = -PI/2, position.z = 2.86):
  //   world_z = 2.86 - local_y   →   local_y = 2.86 - world_z
  const posZ       = 2.86;
  const width      = 14.4;            // -7.2 … +7.2 en world_x
  const northWorldZ = posZ + 2.25;    // = 5.11 — borde norte del plano

  const nx = segmentsX + 1;
  const nz = segmentsZ + 1;
  const count = nx * nz;

  const positions = new Float32Array(count * 3);
  const uvs       = new Float32Array(count * 2);

  for (let iz = 0; iz < nz; iz++) {
    // v = 0 en la costa (borde sur, iz=0), v = 1 en el norte (mar abierto, iz=segmentsZ)
    const v = iz / segmentsZ;
    for (let ix = 0; ix < nx; ix++) {
      const u = ix / segmentsX;
      const worldX     = -width / 2 + u * width;
      const coastZ     = zCoastAt(worldX);           // world_z del litoral en esta columna
      // Interpolar world_z desde la costa (iz=0) hasta el norte (iz=segmentsZ)
      const worldZ     = coastZ + v * (northWorldZ - coastZ);
      const localY     = posZ - worldZ;              // local_y en el plano XY antes de rotar

      const i = iz * nx + ix;
      positions[i * 3 + 0] = worldX;   // local_x = world_x (x no cambia con la rotación)
      positions[i * 3 + 1] = localY;
      positions[i * 3 + 2] = 0;        // el shader añade la elevación de las olas sobre z

      uvs[i * 2 + 0] = u;
      uvs[i * 2 + 1] = v;
    }
  }

  // Índices de triángulos (dos por quad)
  const indices = new Uint32Array(segmentsX * segmentsZ * 6);
  let idx = 0;
  for (let iz = 0; iz < segmentsZ; iz++) {
    for (let ix = 0; ix < segmentsX; ix++) {
      const a = iz * nx + ix;
      const b = iz * nx + ix + 1;
      const c = (iz + 1) * nx + ix;
      const d = (iz + 1) * nx + ix + 1;
      indices[idx++] = a; indices[idx++] = b; indices[idx++] = d;
      indices[idx++] = a; indices[idx++] = d; indices[idx++] = c;
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('uv',       new THREE.BufferAttribute(uvs, 2));
  geo.setIndex(new THREE.BufferAttribute(indices, 1));
  geo.computeVertexNormals();
  return geo;
}

// ── MATERIAL Y MESH DEL MAR ───────────────────────────────────────────────────

const oceanUniforms = {
  uTime:         { value: 0.0 },
  uDeepColor:    { value: new THREE.Color(0x1a6e9a) },   // azul profundo
  uShallowColor: { value: new THREE.Color(0x5ab8d4) },   // azul claro
  uFoamColor:    { value: new THREE.Color(0xddf4ff) },   // blanco espuma
};

// Geometría irregular alineada con el litoral (128×64 segmentos)
const oceanGeo = createCoastAlignedOceanGeo(128, 64);
const oceanMat = new THREE.ShaderMaterial({
  vertexShader:   oceanVertexShader,
  fragmentShader: oceanFragmentShader,
  uniforms:       oceanUniforms,
  transparent:    true,
  side:           THREE.DoubleSide,
});

const ocean = new THREE.Mesh(oceanGeo, oceanMat);
ocean.rotation.x = -Math.PI / 2;
ocean.position.set(0, -0.005, 2.86)  // Ligeramente sobre el plano base
scene.add(ocean);

// ═══════════════════════════════════════════════════════════════
// PLATAFORMA ISLA FLOTANTE — Sistema unificado sin huecos
// Reemplaza TODO el bloque anterior de buildIslandPlatform()
// ═══════════════════════════════════════════════════════════════

(function buildUnifiedPlatform() {

  // ── COORDENADAS ──────────────────────────────────────────────────────────
  const xL      = -7.2;
  const xR      =  7.2;
  const zS      = -3.50;
  const zMarS   =  0.61;
  const zTerrN  = -1.98;  // norte del terreno (empalme con el mapa)

  // Y_top = 0.30 → altura visible en el sur, baja linealmente hasta Y=0 en zMarS
  // El borde norte del terreno (zTerrN=-1.98) queda a surfaceY(-1.98)
  // que es aprox 0.30 * (0.61+1.98)/(0.61+3.50) = 0.30 * 0.63 ≈ 0.19
  // → suficiente para verse y conectar visualmente con el mapa sur
  const Y_top = 0.30;
  const Y_mar = 0.0;
  const H_sub = 0.55;
  const yB    = Y_mar - H_sub;  // base = -0.55

  function surfaceY(z) {
    if (z <= zS)    return Y_top;
    if (z >= zMarS) return Y_mar;
    const t = (z - zS) / (zMarS - zS);  // 0 en zS, 1 en zMarS
    return Y_top * (1 - t);              // baja de Y_top a 0
  }

  // Borde norte sigue la curva real de COAST_POINTS (scope de módulo)
  const zCoastW = zCoastAt(xL);   // borde norte en el extremo oeste
  const zCoastE = zCoastAt(xR);   // borde norte en el extremo este
  function surfaceYatN(z, zN) {
    if (z <= zS)  return Y_top;
    if (z >= zN)  return Y_mar;
    return Y_top * (1 - (z - zS) / (zN - zS));
  }

  // ── MATERIALES ─────────────────────────────────────────────────────────
  const mGrass   = new THREE.MeshLambertMaterial({ color: 0x4a7a2a, flatShading: true, side: THREE.DoubleSide });
  const mSoil    = new THREE.MeshLambertMaterial({ color: 0x6b4220, flatShading: true, side: THREE.DoubleSide });
  const mRock    = new THREE.MeshLambertMaterial({ color: 0x7a7262, flatShading: true, side: THREE.DoubleSide });
  const mBase    = new THREE.MeshLambertMaterial({ color: 0x1a1008, flatShading: true, side: THREE.DoubleSide });
  const mSeaWall = new THREE.MeshLambertMaterial({ color: 0x2a5a7a, flatShading: true, side: THREE.DoubleSide });

  // ── ZONA DEL MAR: paredes, frente norte y fondo de arena ────────────────
  // Coordenadas exclusivas de la zona del mar
  const zMarN  =  5.11;   // borde norte del mar
  const ySeaB  = -0.55;   // fondo del mar (mismo yB)
  const ySeaSurf = -0.005; // superficie del mar (ligerísimamente bajo el shader)

  // Material agua transparente para paredes y frente
  const mSeaGlass = new THREE.MeshLambertMaterial({
    color: 0x1a6e9a,
    transparent: true,
    opacity: 0.45,
    side: THREE.DoubleSide,
  });

  // Material arena para el fondo
  const mSand = new THREE.MeshLambertMaterial({
    color: 0xd4b483,   // arena dorada
    flatShading: true,
    side: THREE.DoubleSide,
  });

  // Fondo de arena — geometría diagonal (borde sur sigue zCoastAt)
  {
    const ssgX = 24, ssgZ = 10;
    const ssp = [], ssi = [];
    for (let iz = 0; iz <= ssgZ; iz++) {
      for (let ix = 0; ix <= ssgX; ix++) {
        const wx = xL + (xR - xL) * ix / ssgX;
        const zSouth = zCoastAt(wx);
        const wz = zSouth + (zMarN - zSouth) * iz / ssgZ;
        ssp.push(wx, ySeaB + (Math.random() - 0.5) * 0.02, wz);
      }
    }
    for (let iz = 0; iz < ssgZ; iz++) {
      for (let ix = 0; ix < ssgX; ix++) {
        const a = iz * (ssgX + 1) + ix, b = a + 1, c = a + (ssgX + 1), d = c + 1;
        ssi.push(a, b, c,  b, d, c);
      }
    }
    const ssg = new THREE.BufferGeometry();
    ssg.setAttribute('position', new THREE.BufferAttribute(new Float32Array(ssp), 3));
    ssg.setIndex(ssi);
    ssg.computeVertexNormals();
    scene.add(new THREE.Mesh(ssg, mSand));
  }

  // Pared OESTE del mar — de zCoastW a zMarN
  quad(xL, ySeaSurf, zCoastW,  xL, ySeaSurf, zMarN,  xL, ySeaB, zMarN,  xL, ySeaB, zCoastW,  mSeaGlass);

  // Pared ESTE del mar — de zMarN a zCoastE
  quad(xR, ySeaSurf, zMarN,  xR, ySeaSurf, zCoastE,  xR, ySeaB, zCoastE,  xR, ySeaB, zMarN,  mSeaGlass);

  // Pared NORTE del mar (frente)
  quad(xL, ySeaSurf, zMarN,  xR, ySeaSurf, zMarN,  xR, ySeaB, zMarN,  xL, ySeaB, zMarN,  mSeaGlass);

  // ── QUAD con DoubleSide — funciona desde cualquier ángulo ───────────────
  // DoubleSide en el material hace que no importe el orden de los vértices
  function quad(ax,ay,az, bx,by,bz, cx,cy,cz, dx,dy,dz, mat) {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array([
      ax,ay,az,  bx,by,bz,  cx,cy,cz,
      ax,ay,az,  cx,cy,cz,  dx,dy,dz,
    ]), 3));
    geo.computeVertexNormals();
    scene.add(new THREE.Mesh(geo, mat));
  }

  // ════════════════════════════════════════════════════════════════════════
  //  1. PARED SUR
  // ════════════════════════════════════════════════════════════════════════
  const totalH = Y_top - yB;
  const yG_s   = Y_top - totalH * 0.13;
  const yT_s   = Y_top - totalH * 0.48;

  quad(xR,Y_top,zS,  xL,Y_top,zS,  xL,yG_s,zS,  xR,yG_s,zS,  mGrass);
  quad(xR,yG_s,zS,   xL,yG_s,zS,   xL,yT_s,zS,  xR,yT_s,zS,  mSoil);
  quad(xR,yT_s,zS,   xL,yT_s,zS,   xL,yB,  zS,  xR,yB,  zS,  mRock);

  // ════════════════════════════════════════════════════════════════════════
  //  2. PARED NORTE (bajo el mar) — diagonal siguiendo COAST_POINTS
  // ════════════════════════════════════════════════════════════════════════
  {
    const nWallSegs = 30;
    for (let i = 0; i < nWallSegs; i++) {
      const t0 = i / nWallSegs, t1 = (i + 1) / nWallSegs;
      const x0 = xL + (xR - xL) * t0, x1 = xL + (xR - xL) * t1;
      const z0 = zCoastAt(x0), z1 = zCoastAt(x1);
      quad(x0, Y_mar, z0,  x1, Y_mar, z1,  x1, yB, z1,  x0, yB, z0,  mSeaWall);
    }
  }

  // ════════════════════════════════════════════════════════════════════════
  //  3. PAREDES LATERALES — con DoubleSide ya no importa el orden
  // ════════════════════════════════════════════════════════════════════════
  const wallSegs = 80;

  function buildSideWall(x, zN) {
    for (let i = 0; i < wallSegs; i++) {
      const t0  = i / wallSegs;
      const t1  = (i + 1) / wallSegs;
      const z0  = zS + (zN - zS) * t0;
      const z1  = zS + (zN - zS) * t1;
      const sY0 = surfaceYatN(z0, zN);
      const sY1 = surfaceYatN(z1, zN);
      const h0  = sY0 - yB;
      const h1  = sY1 - yB;
      const yG0 = sY0 - h0 * 0.13;
      const yT0 = sY0 - h0 * 0.48;
      const yG1 = sY1 - h1 * 0.13;
      const yT1 = sY1 - h1 * 0.48;

      quad(x,sY0,z0,  x,sY1,z1,  x,yG1,z1,  x,yG0,z0,  mGrass);
      quad(x,yG0,z0,  x,yG1,z1,  x,yT1,z1,  x,yT0,z0,  mSoil);
      quad(x,yT0,z0,  x,yT1,z1,  x,yB, z1,  x,yB, z0,  mRock);
    }
  }

  buildSideWall(xL, zCoastW);  // oeste: termina en Z=0.41
  buildSideWall(xR, zCoastE);  // este:  termina en Z=1.47

  // ════════════════════════════════════════════════════════════════════════
  //  4. BASE
  // ════════════════════════════════════════════════════════════════════════
  quad(xL,yB,zS,  xR,yB,zS,  xR,yB,zCoastE,  xL,yB,zCoastW,  mBase);

  // ════════════════════════════════════════════════════════════════════════
  //  5. SUPERFICIE RAMPA — cubre TODO: zS hasta zMarS, ancho completo xL→xR
  //     Cada vértice sigue surfaceY(z) exactamente → tapa TODO el negro
  //     En zona del terreno sur (zS→zTerrN): ondulación verde/marrón
  //     En zona del mapa (zTerrN→zMarS): plana y verde (queda debajo del mapa)
  // ════════════════════════════════════════════════════════════════════════
  const segX = 52;
  const segZ = 56;  // cubre zS(-3.50) → zMarS(0.61) = 4.11 unidades

  function hillFn(wx, uvZ) {
    const r = uvZ;
    return (
      Math.sin(wx * 0.9 + 0.5)  * Math.cos(uvZ * 4.0 + 0.3) * 0.07 * r +
      Math.sin(wx * 1.7 - 1.2)  * Math.sin(uvZ * 6.0 + 0.8) * 0.045 * r +
      Math.cos(wx * 0.5 + uvZ * 2.5)                         * 0.028 * r +
      Math.sin(wx * 2.8 + uvZ * 4.0)                         * 0.015 * r
    );
  }

  const positions = [];
  const colorsArr = [];
  const idxArr    = [];

  const cGreen1 = new THREE.Color(0x3d6e22);
  const cGreen2 = new THREE.Color(0x4a7a2a);
  const cBrown1 = new THREE.Color(0x7a5530);
  const cBrown2 = new THREE.Color(0x546228);

  // Orden ix-exterior / iz-interior para soportar borde norte diagonal
  for (let ix = 0; ix <= segX; ix++) {
    const wx = xL + (xR - xL) * (ix / segX);
    const zN = zCoastAt(wx);
    for (let iz = 0; iz <= segZ; iz++) {
      // iz=0 → zS (sur, alto), iz=segZ → zN (norte, nivel mar)
      const wz        = zS + (zN - zS) * (iz / segZ);
      const baseSlope = surfaceYatN(wz, zN);

      const inTerrain = wz <= zTerrN;
      const terrUvZ   = inTerrain
        ? Math.max(0, (zTerrN - wz) / (zTerrN - zS))
        : 0;
      const elev = inTerrain ? hillFn(wx, terrUvZ) * 0.4 : 0;
      positions.push(wx, baseSlope + elev, wz);

      // ── Color UNIFORME en todo el terreno ─────────────────────────────
      const n1 = (Math.sin(wx * 3.1 + wz * 2.7) + 1) / 2;
      const n2 = (Math.sin(wx * 5.3 - wz * 4.1) + 1) / 2;
      const n3 = (Math.cos(wx * 1.7 + wz * 3.9) + 1) / 2;
      const blend = n1 * 0.5 + n2 * 0.3 + n3 * 0.2;

      let col;
      if      (blend > 0.72) col = cGreen1;
      else if (blend > 0.52) col = cGreen2;
      else if (blend > 0.34) col = cBrown2;
      else                   col = cBrown1;
      colorsArr.push(col.r, col.g, col.b);
    }
  }

  // Índices: vertex(ix,iz) = ix*(segZ+1)+iz
  for (let ix = 0; ix < segX; ix++) {
    for (let iz = 0; iz < segZ; iz++) {
      const a = ix*(segZ+1)+iz, b = (ix+1)*(segZ+1)+iz, c = a+1, d = b+1;
      idxArr.push(a, b, c,  b, d, c);
    }
  }

  const tGeo = new THREE.BufferGeometry();
  tGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(positions), 3));
  tGeo.setAttribute('color',    new THREE.BufferAttribute(new Float32Array(colorsArr), 3));
  tGeo.setIndex(idxArr);
  tGeo.computeVertexNormals();
  scene.add(new THREE.Mesh(tGeo, new THREE.MeshLambertMaterial({
    vertexColors: true, flatShading: true, side: THREE.DoubleSide
  })));

  // ════════════════════════════════════════════════════════════════════════
  //  6. ÁRBOLES — anclados al terreno
  // ════════════════════════════════════════════════════════════════════════
  function getTerrainY(wx, wz) {
    const baseSlope = surfaceYatN(wz, zCoastAt(wx));
    if (wz >= zTerrN || wz <= zS) return baseSlope;
    const uvZ = (wz - zTerrN) / (zS - zTerrN);
    return baseSlope + hillFn(wx, uvZ) * 0.4;
  }

  function createTree(wx, wz, scale, trunkCol, leafDark, leafLight) {
    if (wx < xL+0.15 || wx > xR-0.15) return;
    if (wz > zMarS-0.15 || wz < zS+0.15) return;

    const baseY = getTerrainY(wx, wz);
    const g = new THREE.Group();

    const trkGeo = new THREE.CylinderGeometry(0.022*scale, 0.044*scale, 0.28*scale, 5);
    const tp = trkGeo.attributes.position;
    for (let i=0; i<tp.count; i++) {
      tp.setX(i, tp.getX(i)+(Math.random()-.5)*0.012*scale);
      tp.setZ(i, tp.getZ(i)+(Math.random()-.5)*0.012*scale);
    }
    trkGeo.computeVertexNormals();
    const trunk = new THREE.Mesh(trkGeo,
      new THREE.MeshLambertMaterial({color:trunkCol,flatShading:true}));
    trunk.position.y = 0.14*scale;
    g.add(trunk);

    [{r:.21*scale,h:.26*scale,py:.30*scale,col:leafDark},
     {r:.15*scale,h:.22*scale,py:.46*scale,col:leafLight},
     {r:.09*scale,h:.18*scale,py:.60*scale,col:leafDark},
    ].forEach(({r,h,py,col}) => {
      const cGeo = new THREE.ConeGeometry(r,h,6);
      const cp = cGeo.attributes.position;
      for (let i=0;i<cp.count;i++) {
        if (cp.getY(i)<0) {
          cp.setX(i,cp.getX(i)+(Math.random()-.5)*0.036*scale);
          cp.setZ(i,cp.getZ(i)+(Math.random()-.5)*0.036*scale);
        }
      }
      cGeo.computeVertexNormals();
      const cone = new THREE.Mesh(cGeo,
        new THREE.MeshLambertMaterial({color:col,flatShading:true}));
      cone.position.y=py; cone.rotation.y=Math.random()*Math.PI*2;
      g.add(cone);
    });

    g.position.set(wx, baseY, wz);
    g.rotation.y = Math.random()*Math.PI*2;
    scene.add(g);
  }

  const PAL = [
    {trunk:0x3d2510,dark:0x256018,light:0x357a22},
    {trunk:0x3a2210,dark:0x2d7020,light:0x3d8a2a},
    {trunk:0x4a2e18,dark:0x3a8030,light:0x4a9838},
    {trunk:0x2e1e0a,dark:0x1e5014,light:0x2a6e1e},
  ];

  // Árboles distribuidos en 3 zonas:
  // ZONA SUR: z de -2.10 a -3.35 — toda la anchura
  // ZONA OESTE: x de -7.0 a -5.8 — a lo largo del mapa (z de -1.80 a 0.40)
  // ZONA ESTE:  x de  5.8 a  7.0 — a lo largo del mapa (z de -1.80 a 0.40)
  const treeList = [
    // ── Zona SUR (mismas posiciones anteriores + más dispersión) ─────────
    [-6.8,-2.10,1.12,0],[-5.5,-2.05,1.18,1],[-4.2,-2.13,1.10,2],[-2.9,-2.08,1.15,3],
    [-1.5,-2.11,1.12,0],[-0.1,-2.06,1.18,1],[ 1.3,-2.12,1.10,2],[ 2.7,-2.09,1.16,3],
    [ 4.1,-2.11,1.12,0],[ 5.5,-2.07,1.15,1],[ 6.8,-2.10,1.08,2],

    [-7.0,-2.55,0.98,2],[-5.8,-2.50,1.00,3],[-4.5,-2.58,1.04,0],[-3.1,-2.52,0.96,1],
    [-1.7,-2.50,1.02,2],[-0.3,-2.56,0.99,3],[ 1.1,-2.50,1.04,0],[ 2.5,-2.52,0.97,1],
    [ 3.9,-2.50,1.02,2],[ 5.3,-2.55,0.98,3],[ 6.7,-2.52,0.94,0],

    [-6.5,-2.92,0.92,1],[-5.3,-2.88,0.90,2],[-4.0,-2.94,0.94,3],[-2.6,-2.90,0.89,0],
    [-1.2,-2.92,0.93,1],[ 0.3,-2.88,0.91,2],[ 1.7,-2.92,0.94,3],[ 3.2,-2.90,0.90,0],
    [ 4.6,-2.92,0.92,1],[ 6.0,-2.88,0.89,2],[ 7.0,-2.92,0.86,3],

    [-6.8,-3.25,0.82,3],[-5.5,-3.20,0.84,0],[-4.1,-3.28,0.80,1],[-2.7,-3.22,0.83,2],
    [-1.3,-3.25,0.81,3],[ 0.1,-3.20,0.84,0],[ 1.5,-3.25,0.80,1],[ 2.9,-3.22,0.83,2],
    [ 4.4,-3.25,0.82,3],[ 5.8,-3.20,0.84,0],[ 7.0,-3.24,0.79,1],

    // ── Zona OESTE (borde izquierdo del mapa) ────────────────────────────
    [-6.9,-1.80,0.95,2],[-6.7,-1.40,0.90,3],[-7.0,-1.00,0.88,0],
    [-6.8,-0.60,0.92,1],[-6.9,-0.20,0.89,2],[-7.0, 0.20,0.86,3],

    [-6.2,-1.70,1.00,0],[-6.4,-1.25,0.95,1],[-6.3,-0.80,0.92,2],
    [-6.5,-0.38,0.90,3],[-6.2, 0.05,0.87,0],

    // ── Zona ESTE (borde derecho del mapa) ───────────────────────────────
    [ 6.9,-1.80,0.95,3],[ 6.7,-1.40,0.90,0],[ 7.0,-1.00,0.88,1],
    [ 6.8,-0.60,0.92,2],[ 6.9,-0.20,0.89,3],[ 7.0, 0.20,0.86,0],

    [ 6.2,-1.70,1.00,1],[ 6.4,-1.25,0.95,2],[ 6.3,-0.80,0.92,3],
    [ 6.5,-0.38,0.90,0],[ 6.2, 0.05,0.87,1],
  ];

  treeList.forEach(([x,z,s,pi]) => {
    const p = PAL[pi];
    createTree(x,z,s,p.trunk,p.dark,p.light);
  });

  function addRock(wx,wz,s) {
    if (wx<xL+0.1||wx>xR-0.1||wz>zMarS-0.15||wz<zS+0.1) return;
    const by = getTerrainY(wx,wz);
    const rGeo = new THREE.DodecahedronGeometry(0.055*s,0);
    const rp = rGeo.attributes.position;
    for (let i=0;i<rp.count;i++) {
      rp.setX(i,rp.getX(i)*(0.65+Math.random()*0.7));
      rp.setY(i,rp.getY(i)*(0.4+Math.random()*0.55));
      rp.setZ(i,rp.getZ(i)*(0.65+Math.random()*0.7));
    }
    rGeo.computeVertexNormals();
    const rock = new THREE.Mesh(rGeo,
      new THREE.MeshLambertMaterial({color:0x8a8070,flatShading:true}));
    rock.position.set(wx,by+0.022*s,wz);
    rock.rotation.set(Math.random()*Math.PI,Math.random()*Math.PI,Math.random()*Math.PI);
    scene.add(rock);
  }

  // Rocas: sur, bordes este y oeste del mapa
  [
    // Sur
    [-5.8,-2.22,1.0],[-4.2,-2.55,0.85],[-2.7,-2.18,1.1],[-1.0,-2.68,0.90],
    [ 0.5,-2.30,1.05],[ 2.0,-2.58,0.80],[ 3.5,-2.22,1.10],[ 5.0,-2.65,0.88],
    [ 6.4,-2.38,0.95],[-6.0,-2.88,0.80],[-3.2,-2.92,0.90],[ 1.4,-3.10,0.75],
    [ 4.2,-3.05,0.85],[-5.5,-3.28,0.70],[ 2.8,-3.22,0.78],[ 6.8,-3.15,0.72],
    // Oeste
    [-6.8,-1.60,0.80],[-7.0,-1.10,0.75],[-6.6,-0.55,0.82],[-6.9, 0.10,0.70],
    [-6.3,-0.90,0.78],[-6.7, 0.35,0.72],
    // Este
    [ 6.8,-1.60,0.80],[ 7.0,-1.10,0.75],[ 6.6,-0.55,0.82],[ 6.9, 0.10,0.70],
    [ 6.3,-0.90,0.78],[ 6.7, 0.35,0.72],
  ].forEach(([x,z,s])=>addRock(x,z,s));

})();





// --- Low-poly fishing boats with wake ---
function createBoat(hullColor, sailColor) {
    const g = new THREE.Group();
    // Hull shape (boat profile from above: pointed bow, wide stern)
    const hs = new THREE.Shape();
    hs.moveTo(0, 0.06);
    hs.lineTo(0.02, 0.02);
    hs.lineTo(0.025, -0.01);
    hs.lineTo(0.02, -0.04);
    hs.lineTo(0.008, -0.06);
    hs.lineTo(-0.008, -0.06);
    hs.lineTo(-0.02, -0.04);
    hs.lineTo(-0.025, -0.01);
    hs.lineTo(-0.02, 0.02);
    const hGeo = new THREE.ExtrudeGeometry(hs, { depth: 0.012, bevelEnabled: false });
    const hull = new THREE.Mesh(hGeo, new THREE.MeshLambertMaterial({ color: hullColor, flatShading: true }));
    hull.rotation.x = -Math.PI / 2;
    g.add(hull);
    // Sail (triangle visible from above)
    const ss = new THREE.Shape();
    ss.moveTo(0, 0.035);
    ss.lineTo(0.025, -0.015);
    ss.lineTo(-0.005, -0.015);
    const sail = new THREE.Mesh(new THREE.ShapeGeometry(ss),
        new THREE.MeshLambertMaterial({ color: sailColor, side: THREE.DoubleSide }));
    sail.rotation.x = -Math.PI / 2;
    sail.position.y = 0.015;
    g.add(sail);
    // Mast (tiny cylinder, dot from above)
    const mast = new THREE.Mesh(
        new THREE.CylinderGeometry(0.003, 0.003, 0.06, 4),
        new THREE.MeshLambertMaterial({ color: 0x4a3728 }));
    mast.position.y = 0.03;
    g.add(mast);
    // Wake (V-shape behind boat)
    const ws = new THREE.Shape();
    ws.moveTo(0, -0.06);
    ws.lineTo(-0.05, -0.30);
    ws.lineTo(0, -0.22);
    ws.lineTo(0.05, -0.30);
    ws.closePath();
    const wake = new THREE.Mesh(new THREE.ShapeGeometry(ws),
        new THREE.MeshBasicMaterial({ color: 0xe8f4ff, transparent: true, opacity: 0.7, side: THREE.DoubleSide }));
    wake.rotation.x = -Math.PI / 2;
    wake.position.y = -0.005;
    wake.name = 'wake';
    g.add(wake);
    return g;
}

const boats = [];
