boat0.position.set(-3.5, -0.02, 2.0);
boat0.rotation.y = -Math.PI/2;
boat0.scale.setScalar(1.0);
scene.add(boat0);
boats.push({ group: boat0, baseZ: 2.0, phase: 0.0, speed: 0.003 });
