window.scene = scene;
window._expandPolygon = (name) => {
    const p = polygons.find(x => x.userData.name === name);
    if (p) animatePolygon(p, true);
    return p ? 'expanding ' + name : 'not found';
};

// Animation with pulse
let _t = 0;
function animate() {
    requestAnimationFrame(animate);
    _t += 0.016;
    oceanUniforms.uTime.value = _t;
    activeModules.forEach(m => m.update(_t));
    const pulse = 0.5 + 0.5 * Math.sin(_t * 3);
    bulbMat.opacity = 0.6 + 0.4 * pulse;
    glowMat.opacity = 0.05 + 0.25 * pulse;
    // UFO platform animation (time-based with ease-out)
    if (polyAnimTarget) {
        const p = polyAnimTarget.poly;
        const cX = p.userData.centroidX;
        const cZ = p.userData.centroidZ;
        const tY = polyAnimTarget.targetY;
        const tS = polyAnimTarget.targetScale;
        const tW = polyAnimTarget.targetCenterW;
        const tTh = polyAnimTarget.targetThickness;
        const elapsed = performance.now() - polyAnimTarget.startTime;
        const duration = polyAnimTarget.expanding ? 800 : 500;
        const t = Math.min(elapsed / duration, 1);
        const e = 1 - Math.pow(1 - t, 3);  // ease-out cubic
        // Interpolate from start to target
        const newS = polyAnimTarget.startS + (tS - polyAnimTarget.startS) * e;
        const newTh = polyAnimTarget.startThickness + (tTh - polyAnimTarget.startThickness) * e;
        p.scale.set(newS, newTh, newS);
        polyCenterWeight = polyAnimTarget.startW + (tW - polyAnimTarget.startW) * e;
        p.position.x = cX * (1 - newS - polyCenterWeight);
        p.position.z = cZ * (1 - newS - polyCenterWeight);
        p.position.y = polyAnimTarget.startY + (tY - polyAnimTarget.startY) * e;
        // Position buildings on platform + animate rotation (flat -> standing)
        if (p.userData.buildings) {
            const worldCX = p.position.x + cX * newS;
            const worldCZ = p.position.z + cZ * newS;
            p.userData.buildings.forEach(b => {
                b.mesh.position.x = worldCX + b.offsetX * newS;
                b.mesh.position.z = worldCZ + b.offsetZ * newS;
                b.mesh.position.y = p.position.y + p.userData.depth * p.scale.y + 0.005;
                b.mesh.scale.setScalar(newS);
                // Animate rotation: flat (flatRotX) -> standing (0)
                if (polyAnimTarget.expanding) {
                    b.mesh.visible = true;
                    b.mesh.rotation.x = b.flatRotX * (1 - e);
                    // Offset Y when standing so base sits on platform
                    b.mesh.position.y += b.heightOffset * newS * e;
                } else {
                    b.mesh.rotation.x = b.flatRotX * e;
                    b.mesh.position.y += b.heightOffset * newS * (1 - e);
                }
            });
        }
        // Done?
        if (t >= 1) {
            if (polyAnimTarget.expanding) {
                p.scale.set(tS, tTh, tS);
                polyCenterWeight = tW;
                p.position.x = cX * (1 - tS - tW);
                p.position.z = cZ * (1 - tS - tW);
                p.position.y = tY;
                // Snap buildings to standing
                if (p.userData.buildings) {
                    p.userData.buildings.forEach(b => { b.mesh.rotation.x = 0; });
                }
                polyAnimTarget = null;
            } else {
                resetBuildings(p);
                p.position.set(0, 0, 0);
                p.scale.set(1, 1, 1);
                p.renderOrder = 0;
                p.material.color.setHex(p.userData.originalColor);
                polyCenterWeight = 0;
                polyAnimTarget = null;
            }
        }
    }
    // Camera animation (cenital <-> isometric)
    if (cameraAnimTarget) {
        const elapsed = performance.now() - cameraAnimTarget.startTime;
        const t = Math.min(elapsed / cameraAnimTarget.duration, 1);
        const e = 1 - Math.pow(1 - t, 3);  // ease-out cubic
        camera.position.lerpVectors(cameraAnimTarget.startPos, cameraAnimTarget.endPos, e);
        controls.target.lerpVectors(cameraAnimTarget.startTarget, cameraAnimTarget.endTarget, e);
        if (t >= 1) {
            camera.position.copy(cameraAnimTarget.endPos);
            controls.target.copy(cameraAnimTarget.endTarget);
            controls.enabled = true;
            controls.enableRotate = cameraAnimTarget.expanding;
            isPolyAnimating = false;
            cameraAnimTarget = null;
        }
    }
    // --- Boat navigation animation ---
    boats.forEach(b => {
        // Navigate along coast (X axis)
        b.group.position.x += b.speed;
        // Wrap around when out of view
        if (b.speed > 0 && b.group.position.x > 7) b.group.position.x = -7;
        if (b.speed < 0 && b.group.position.x < -7) b.group.position.x = 7;
        // Gentle Z oscillation (approach/recede from coast)
        b.group.position.z = b.baseZ + Math.sin(_t * 0.15 + b.phase) * 0.04;
        // Subtle Y bobbing
        b.group.position.y = -0.02 + Math.sin(_t * 1.2 + b.phase) * 0.004;
        // Gentle roll and pitch
        b.group.rotation.z = Math.sin(_t * 0.8 + b.phase) * 0.04;
        b.group.rotation.x = Math.sin(_t * 0.6 + b.phase * 0.7) * 0.02;
        // Heading wobble (simulates rudder corrections)
        const baseHeading = b.speed > 0 ? -Math.PI/2 : Math.PI/2;
        b.group.rotation.y = baseHeading + Math.sin(_t * 0.2 + b.phase) * 0.08;
        // Animate wake opacity
        const wake = b.group.getObjectByName('wake');
        if (wake) wake.material.opacity = 0.55 + Math.sin(_t * 4.0 + b.phase) * 0.15;
    });
    // ─── Animate plaza characters ────────────────────────────────────────────
    allPlazas.forEach(({ plaza, polygon }) => {
        if (!plaza.visible) return;
        const state = plaza.userData.plazaState;
        _animatePlazaCharacter(state, 0.016, _t, polygon.userData.name, polygon);
        // Bubble animation
        if (plaza.userData.bubbles) {
            plaza.userData.bubbles.forEach((b, i) => {
                b.rotation.y += 0.016 * 0.9;
                b.position.y = 5.8 * state.S + Math.sin(_t * 1.2 + i * 2.1) * 0.2 * state.S;
            });
        }
    });
    // Pulse búsqueda
    if (_searchMarker) {
        searchHlMat.opacity = 0.65 + 0.35 * Math.abs(Math.sin(_t * 3));
        searchHl.scale.setScalar(1.0 + 0.4 * Math.abs(Math.sin(_t * 1.8)));
    }
    controls.update();
    renderer.render(scene, camera);
}
animate();

// ===== BÚSQUEDA DE MUNICIPIO =====
const _searchInput = document.getElementById('search-municipio');
const _searchDrop  = document.getElementById('search-dropdown');

function _showMarkerInfo(m) {
    searchHl.position.copy(m.position);
    _searchMarker = m;
    const d = m.userData;
    document.getElementById('card-name').textContent = d.name;
    document.getElementById('card-capital').textContent = 'Capital: ' + d.capital;
    document.getElementById('card-pop').textContent = d.population.toLocaleString('es-ES') + ' hab.';
    document.getElementById('card-alt').textContent = d.altitude_m + ' m';
    document.getElementById('card-area').textContent = d.area_km2 + ' km²';
    document.getElementById('card-density').textContent = d.density + ' hab/km²';
    document.getElementById('card-comarca').textContent = 'Comarca: ' + d.comarca;
    document.getElementById('card-fact').textContent = d.fun_fact;
    card.style.display = 'block';
    if (hint) hint.style.display = 'none';
    selectedMarker = m;
}

function _clearSearchHighlight() {
    searchHlMat.opacity = 0;
    searchHl.scale.setScalar(1);
    _searchMarker = null;
}

function closeInfoCard() {
    card.style.display = 'none';
    if (_searchInput) _searchInput.value = '';
    if (_searchDrop)  { _searchDrop.innerHTML = ''; _searchDrop.classList.remove('open'); }
    _clearSearchHighlight();
}
window.closeInfoCard = closeInfoCard;

// ─── OSM map controller (pan + zoom) ─────────────────────────────────────────
function _latLonToTileFrac(lat, lon, z) {
    const n = Math.pow(2, z);
    const fx = (lon + 180) / 360 * n;
    const lr = lat * Math.PI / 180;
    const fy = (1 - Math.log(Math.tan(lr) + 1 / Math.cos(lr)) / Math.PI) / 2 * n;
    return { fx, fy };
}

function _createOsmMapController(container, pinEl, lat, lon, initZoom) {
    let _lat = lat, _lon = lon, _z = initZoom;
    let panX = 0, panY = 0;
    let isDragging = false, lastMX = 0, lastMY = 0;

    function render() {
        container.innerHTML = '';
        const SZ = 256;
        const W = container.offsetWidth  || 320;
        const H = container.offsetHeight || 200;
        const { fx, fy } = _latLonToTileFrac(_lat, _lon, _z);
        const tx = Math.floor(fx), ty = Math.floor(fy);
        const ox = W / 2 - (fx - tx) * SZ + panX;
        const oy = H / 2 - (fy - ty) * SZ + panY;
        for (let dy = -2; dy <= 2; dy++) {
            for (let dx = -2; dx <= 2; dx++) {
                const img = document.createElement('img');
                img.src = `https://tile.openstreetmap.org/${_z}/${tx + dx}/${ty + dy}.png`;
                img.style.cssText = `position:absolute;left:${ox + dx * SZ}px;top:${oy + dy * SZ}px;width:${SZ}px;height:${SZ}px;user-select:none;`;
                img.draggable = false;
                container.appendChild(img);
            }
        }
        if (pinEl) {
            pinEl.style.left = (W / 2 + panX) + 'px';
            pinEl.style.top  = (H / 2 + panY) + 'px';
        }
    }

    function zoom(delta) {
        _z = Math.max(13, Math.min(19, _z + delta));
        panX = 0; panY = 0;
        render();
    }

    container.style.cursor = 'grab';
    container.style.userSelect = 'none';

    container.addEventListener('mousedown', e => {
        isDragging = true; lastMX = e.clientX; lastMY = e.clientY;
        container.style.cursor = 'grabbing';
        e.preventDefault();
    });
    container.addEventListener('mousemove', e => {
        if (!isDragging) return;
        panX += e.clientX - lastMX;
        panY += e.clientY - lastMY;
        lastMX = e.clientX; lastMY = e.clientY;
        render();
    });
    container.addEventListener('mouseup',    () => { isDragging = false; container.style.cursor = 'grab'; });
    container.addEventListener('mouseleave', () => { isDragging = false; container.style.cursor = 'grab'; });
    container.addEventListener('touchstart', e => {
        if (e.touches.length === 1) {
            isDragging = true; lastMX = e.touches[0].clientX; lastMY = e.touches[0].clientY;
        }
    }, { passive: true });
    container.addEventListener('touchmove', e => {
        if (!isDragging || e.touches.length !== 1) return;
        panX += e.touches[0].clientX - lastMX;
        panY += e.touches[0].clientY - lastMY;
        lastMX = e.touches[0].clientX; lastMY = e.touches[0].clientY;
        render();
    }, { passive: true });
    container.addEventListener('touchend', () => { isDragging = false; });

    return { render, zoom };
}

// ─── Building card (waypoints) ────────────────────────────────────────────────
let _bcController = null;

function _hideBuildingCard() {
    const bc = document.getElementById('building-card');
    if (bc) bc.style.display = 'none';
}

function _showBuildingCard(wd) {
    const bc = document.getElementById('building-card');
    if (!bc) return;
    document.getElementById('bc-name').textContent = wd.name;
    document.getElementById('bc-desc').textContent = wd.description;
    const yr = document.getElementById('bc-year-row');
    const ar = document.getElementById('bc-artist-row');
    if (wd.type === 'monument' && wd.year) {
        yr.style.display = ''; document.getElementById('bc-year').textContent = wd.year;
        ar.style.display = ''; document.getElementById('bc-artist').textContent = wd.artist || '—';
    } else { yr.style.display = 'none'; ar.style.display = 'none'; }
    bc.style.display = 'flex';
    _bcController = _createOsmMapController(
        document.getElementById('bc-osm-tiles'),
        document.getElementById('bc-osm-pin'),
        wd.lat, wd.lon, 16
    );
    _bcController.render();
}

window.closeBuildingCard = function() {
    _hideBuildingCard();
    if (selectedPolygon) {
        const pe = allPlazas.find(pe => pe.polygon === selectedPolygon);
        if (pe) {
            const st = pe.plaza.userData.plazaState;
            st.targetPosLocal.set(0, 0.68 * st.S, 0);
            st.isMoving = true; st.returningToCenter = true;
            st.activeBuilding = null; st.activeSign = null;
        }
    }
};

window._osmZoom = function(delta) {
    if (_bcController) _bcController.zoom(delta);
};

// ─── Market card (rutas de compras) — usa #modal-general ─────────────────────
async function _showMarketCard(municipio, _cfg) {
    const modal = document.getElementById('modal-general');
    if (!modal) return;
    // Fondo azul inline (CSS puede estar en caché) + clase para item-cards
    modal.classList.add('modal-mercado');
    const _mc = modal.querySelector('.modal-content');
    if (_mc) _mc.style.background = '#C4D8E8';
    // Configurar cabecera
    const titleEl = document.getElementById('modal-titulo');
    if (titleEl) titleEl.textContent = '🏪 Mercado de Gijón';
    const tagEl = document.getElementById('modal-municipio-tag');
    if (tagEl) tagEl.textContent = '';
    // Ocultar filtros ocio y botones de paginación
    const ocioFilters = document.getElementById('ocio-filters');
    if (ocioFilters) ocioFilters.style.display = 'none';
    const btnMas = document.getElementById('btn-cargar-mas');
    if (btnMas) btnMas.style.display = 'none';
    const btnTrip = document.getElementById('btn-tripadvisor');
    if (btnTrip) btnTrip.style.display = 'none';

    const contenedor = document.getElementById('contenedor-items');
    if (!contenedor) return;
    contenedor.innerHTML = '<div style="color:#555;font-size:13px;padding:8px 0">Cargando rutas…</div>';
    modal.style.display = 'flex';

    try {
        const resp = await fetch(`/api/mercado/${encodeURIComponent(municipio)}`);
        const rutas = await resp.json();
        contenedor.innerHTML = '';
        rutas.forEach(r => {
            const card = document.createElement('div');
            card.className = 'item-card';
            card.style.borderLeftColor = r.color;
            card.style.background = 'rgba(255,255,255,0.75)';
            card.innerHTML = `
                <div class="item-info">
                    <h3>${r.icon} ${r.label}</h3>
                    <p>${r.count} tiendas</p>
                </div>
                <div class="item-links">
                    <button class="btn-ver-lugar">Ver</button>
                </div>`;
            card.querySelector('.btn-ver-lugar').addEventListener('click', () => _loadMarketShops(municipio, r));
            contenedor.appendChild(card);
        });
    } catch(e) {
        contenedor.innerHTML = `<div style="color:#c00;font-size:13px">Error cargando rutas</div>`;
    }
}

async function _loadMarketShops(municipio, ruta) {
    const contenedor = document.getElementById('contenedor-items');
    if (!contenedor) return;
    // Título de la ruta (sin botón volver aquí — va al final)
    contenedor.innerHTML = '';
    const rutaTitle = document.createElement('p');
    rutaTitle.style.cssText = 'font-size:15px;font-weight:700;color:#111;margin:0 0 10px;padding:0 2px;';
    rutaTitle.textContent = `${ruta.icon} ${ruta.label}`;
    contenedor.appendChild(rutaTitle);

    const shopList = document.createElement('div');
    shopList.style.paddingBottom = '0';   // se ajusta abajo cuando hay scroll
    shopList.innerHTML = `<div style="color:#555;font-size:13px;padding:8px 0">Cargando tiendas…</div>`;
    contenedor.appendChild(shopList);

    // Botón Volver — sticky al fondo (visible aunque haya scroll)
    const backBtn = document.createElement('button');
    backBtn.style.cssText = 'position:sticky;bottom:0;width:100%;padding:10px;background:#650E01;color:#fff;border:none;border-radius:0 0 4px 4px;font-family:\'Inter\',sans-serif;font-size:14px;font-weight:600;cursor:pointer;margin-top:8px;transition:background 0.2s;';
    backBtn.textContent = 'Volver a rutas';
    backBtn.addEventListener('mouseover', () => { backBtn.style.background = '#8a1501'; });
    backBtn.addEventListener('mouseout',  () => { backBtn.style.background = '#650E01'; });
    backBtn.addEventListener('click', () => {
        window.closePlaceCard && window.closePlaceCard();
        _showMarketCard(municipio, null);
    });
    contenedor.appendChild(backBtn);

    try {
        const resp = await fetch(`/api/mercado/${encodeURIComponent(municipio)}/${ruta.id}`);
        const shops = await resp.json();
        shopList.innerHTML = '';
        if (!shops.length) {
            shopList.innerHTML = '<div style="color:#555;font-size:13px">No hay tiendas en esta ruta aún.</div>';
            return;
        }
        shops.forEach(s => {
            const card = document.createElement('div');
            card.className = 'item-card';
            card.style.borderLeftColor = ruta.color;
            card.style.background = 'rgba(255,255,255,0.75)';
            card.innerHTML = `
                <div class="item-info">
                    <h3>${s.nombre}</h3>
                    ${s.direccion ? `<p>${s.direccion}</p>` : ''}
                    ${s.horario  ? `<p>🕐 ${s.horario}</p>` : ''}
                </div>
                ${(s.lat && s.lon) ? '<div class="item-links"><button class="btn-ver-lugar">Ver</button></div>' : ''}`;
            if (s.lat && s.lon) {
                card.querySelector('.btn-ver-lugar').addEventListener('click', () => _showPlaceCard({
                    nombre: s.nombre,
                    tipo_label: ruta.label,
                    description: s.descripcion,
                    direccion: s.direccion,
                    horario: s.horario,
                    lat: s.lat, lon: s.lon,
                }, { centered: true }));
            }
            shopList.appendChild(card);
        });
        // Padding para que el botón sticky no tape el último ítem
        shopList.style.paddingBottom = '4px';
    } catch(e) {
        shopList.innerHTML = `<div style="color:#c00;font-size:13px">Error cargando tiendas</div>`;
    }
}

window.closeMarketCard = function() {
    cerrarModal();   // cierra modal-general, place-card y envía monigote al centro
    if (selectedPolygon) {
        const plazaEntry = allPlazas.find(pe => pe.polygon === selectedPolygon);
        if (plazaEntry) plazaEntry.plaza.userData.plazaState.activeMarket = null;
    }
};

