const CUISINE_LABELS = {
    'italian': 'Cocina italiana', 'spanish': 'Cocina española',
    'pizza': 'Pizzería', 'seafood': 'Marisquería', 'burger': 'Hamburguesas',
    'asian': 'Cocina asiática', 'chinese': 'Cocina china', 'japanese': 'Cocina japonesa',
    'mexican': 'Cocina mexicana', 'french': 'Cocina francesa', 'kebab': 'Kebab',
    'tapas': 'Tapas', 'international': 'Internacional', 'sushi': 'Sushi',
    'regional': 'Cocina regional', 'steak_house': 'Asador',
};

let _pcController = null;

function _showPlaceCard(item, opts = {}) {
    const pc = document.getElementById('place-card');
    if (!pc) return;
    document.getElementById('pc-name').textContent = item.nombre;
    document.getElementById('pc-tipo-label').textContent = item.tipo_label || item.tipo || '';
    let desc = '';
    if (item.cuisine) desc = CUISINE_LABELS[item.cuisine] || item.cuisine;
    else if (item.description) desc = item.description;
    document.getElementById('pc-desc').textContent = desc;
    const dirEl = document.getElementById('pc-dir');
    if (dirEl) dirEl.textContent = item.direccion || '';
    const horEl = document.getElementById('pc-horario');
    if (horEl) horEl.textContent = item.horario ? `🕐 ${item.horario}` : '';
    _pcController = _createOsmMapController(
        document.getElementById('pc-osm-tiles'),
        document.getElementById('pc-osm-pin'),
        item.lat, item.lon, 17
    );
    _pcController.render();
    if (opts.centered) {
        const modalW = Math.min(420, Math.round(window.innerWidth * 0.92));
        pc.style.left  = '';
        pc.style.right = (modalW + 10) + 'px';
        pc.style.top   = '50px';
    } else {
        const modalPanelW = Math.min(420, Math.round(window.innerWidth * 0.92));
        const pcWidth = 360;
        const margin = 10;
        const left = Math.max(margin, window.innerWidth - modalPanelW - pcWidth - margin);
        pc.style.left = left + 'px';
        pc.style.top  = '60px';
    }
    pc.style.display = 'flex';
    window._pcOsmZoom = d => _pcController.zoom(d);
}
window._showPlaceCard = _showPlaceCard;

window.closePlaceCard = function() {
    const pc = document.getElementById('place-card');
    if (pc) pc.style.display = 'none';
};

if (_searchInput && _searchDrop) {
    _searchInput.addEventListener('input', function() {
        const q = this.value.trim().toLowerCase();
        _searchDrop.innerHTML = '';
        if (!q) {
            _searchDrop.classList.remove('open');
            _clearSearchHighlight();
            return;
        }
        // Matches: startsWith first, then includes (deduplicated, max 8)
        const sw = markers.filter(m => m.userData.name.toLowerCase().startsWith(q));
        const inc = markers.filter(m => !m.userData.name.toLowerCase().startsWith(q) && m.userData.name.toLowerCase().includes(q));
        const results = [...sw, ...inc].slice(0, 8);
        if (!results.length) {
            _searchDrop.classList.remove('open');
            _clearSearchHighlight();
            return;
        }
        results.forEach(m => {
            const item = document.createElement('div');
            item.className = 'dd-item';
            // Bold the matching prefix
            const name = m.userData.name;
            const idx = name.toLowerCase().indexOf(q);
            item.innerHTML = name.slice(0, idx) + '<strong>' + name.slice(idx, idx + q.length) + '</strong>' + name.slice(idx + q.length);
            item.addEventListener('mousedown', function(e) {
                e.preventDefault(); // keep input focused
                _searchInput.value = m.userData.name;
                _searchDrop.innerHTML = '';
                _searchDrop.classList.remove('open');
                _showMarkerInfo(m);
            });
            _searchDrop.appendChild(item);
        });
        _searchDrop.classList.add('open');
        // If only one exact match, show immediately
        if (results.length === 1) _showMarkerInfo(results[0]);
    });

    // Hide dropdown on blur
    _searchInput.addEventListener('blur', function() {
        setTimeout(() => { _searchDrop.classList.remove('open'); }, 150);
    });
    _searchInput.addEventListener('focus', function() {
        if (_searchDrop.children.length) _searchDrop.classList.add('open');
    });
}

