function getTurismoUrl(municipio) {
    const slug = municipio
        .toLowerCase()
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .replace(/,\s*/g, '-')
        .replace(/\s+/g, '-')
        .replace(/-+/g, '-')
        .replace(/^-|-$/g, '');
    return TURISMO_URLS_PROPIAS[slug]
        || `https://www.turismoasturias.es/descubre/concejos/${slug}`;
}

async function abrirModal(municipio, categoria) {
    const modal = document.getElementById('modal-general');
    const titulo = document.getElementById('modal-titulo');
    const subtitulo = document.getElementById('modal-municipio-tag');
    const contenedor = document.getElementById('contenedor-items');

    //Limpiamos clases antiguas
    modal.className = `modal modal-${categoria}`;

    // Mostrar u ocultar filtros según categoría
    const filtrosDiv = document.getElementById('ocio-filters');
    if (categoria === 'ocio') {
        filtrosDiv.style.display = 'flex';
        currentFilterTipo = 'todos';
        document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
        document.querySelector('.filter-btn[data-tipo="todos"]').classList.add('active');
    } else {
        filtrosDiv.style.display = 'none';
    }

    // 1. Configurar títulos visuales
    const titulos = {
        'restaurantes': '🍴 Restaurantes y Bares',
        'ocio': '🎭 Cultura, Museos y Monumentos',
        'tiendas': '🛍️ Tiendas y Comercios'
    };

    titulo.innerText = titulos[categoria] || 'Información';
    subtitulo.innerText = `Explorando el concejo de ${municipio}`;
    contenedor.innerHTML = '<div class="loader">Cargando...</div>';
    modal.style.display = 'flex';

    // Cancelar fetch anterior si existe (evita race conditions)
    if (currentAbortCtrl) currentAbortCtrl.abort();
    currentAbortCtrl = new AbortController();

    try {
        // 2. Llamada a la API que configuramos en Python
        const response = await fetch(`/api/${categoria}/${municipio.toLowerCase()}`, { signal: currentAbortCtrl.signal });
        const data = await response.json();

        currentData = data.resultados;
        currentIndex = 0;
        contenedor.innerHTML = ''; // Limpiar loader

        configurarBotones(municipio, categoria);

        if (currentData.length > 0) {
            renderizarBloque();
        } else {
            contenedor.innerHTML = `<p>No se han encontrado datos en esta categoría para ${municipio}.</p>`;
        }
    } catch (error) {
        if (error.name === 'AbortError') return;
        contenedor.innerHTML = '<p>Error al conectar con el servidor.</p>';
    }
}

function renderizarBloque() {
    const contenedor = document.getElementById('contenedor-items');
    const btnMas  = document.getElementById('btn-cargar-mas');
    const btnTrip = document.getElementById('btn-tripadvisor');

    const tiposPermitidos = OCIO_TIPO_MAP[currentFilterTipo];
    const dataFiltrada = tiposPermitidos
        ? currentData.filter(item => tiposPermitidos.includes((item.tipo || '').trim()))
        : currentData;

    const siguienteBloque = dataFiltrada.slice(currentIndex, currentIndex + PAGE_SIZE);

    // Empty state: filtro sin resultados
    if (siguienteBloque.length === 0 && currentIndex === 0) {
        contenedor.innerHTML = '<p class="empty-msg">No hay resultados para este filtro.</p>';
        btnMas.style.display  = 'none';
        btnTrip.style.display = btnTrip.onclick ? 'block' : 'none';
        return;
    }

    siguienteBloque.forEach(item => {
        const card = document.createElement('div');
        card.className = 'item-card';
        card.innerHTML = `
            <div class="item-info">
                <h3>${item.nombre}</h3>
            </div>
            <div class="item-links">
                <button class="btn-ver-lugar">Ver</button>
            </div>
        `;
        card.querySelector('.btn-ver-lugar').addEventListener('click', () => _showPlaceCard(item));
        contenedor.appendChild(card);
    });

    currentIndex += PAGE_SIZE;
    const hayMas = currentIndex < dataFiltrada.length;

    btnMas.style.display  = hayMas ? 'block' : 'none';
    btnTrip.style.display = (!hayMas && btnTrip.onclick) ? 'block' : 'none';
}

function activarFiltroOcio(tipo) {
    currentFilterTipo = tipo;
    currentIndex = 0;
    document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
    document.querySelector(`.filter-btn[data-tipo="${tipo}"]`).classList.add('active');
    document.getElementById('contenedor-items').innerHTML = '';
    renderizarBloque();
}
window.activarFiltroOcio = activarFiltroOcio;

function configurarBotones(municipio, categoria) {
    const btnTrip = document.getElementById('btn-tripadvisor');
    const btnMas  = document.getElementById('btn-cargar-mas');

    // "Ver más" llama a renderizarBloque() al hacer clic
    btnMas.onclick = renderizarBloque;

    // Configurar btn-tripadvisor según categoría, ocultarlo inicialmente
    // (aparece en renderizarBloque cuando se agoten los resultados)
    btnTrip.style.display = 'none';
    if (categoria === 'restaurantes') {
        btnTrip.textContent = '🍽️ Ver en TripAdvisor';
        btnTrip.onclick = () =>
            window.open(`https://www.tripadvisor.es/Search?q=${encodeURIComponent(municipio)}+restaurantes`, '_blank');
    } else if (categoria === 'ocio') {
        btnTrip.textContent = '🌐 Turismo oficial';
        btnTrip.onclick = () =>
            window.open(getTurismoUrl(municipio), '_blank');
    } else {
        btnTrip.onclick = null;
    }
}

window.abrirModal = abrirModal;

function cerrarModal() {
    const modal = document.getElementById('modal-general');
    if (modal) {
        modal.style.display = 'none';
        modal.classList.remove('modal-mercado');
        const _mc = modal.querySelector('.modal-content');
        if (_mc) _mc.style.background = '';
    }
    window.closePlaceCard && window.closePlaceCard();
    // Monigote vuelve al centro si hay plaza activa
    if (selectedPolygon) {
        const plazaEntry = allPlazas.find(pe => pe.polygon === selectedPolygon);
        if (plazaEntry) {
            const state = plazaEntry.plaza.userData.plazaState;
            const _S = state.S;
            state.targetPosLocal.set(0, 0.68 * _S, 0);
            state.isMoving = true;
            state.returningToCenter = true;
            state.activeSign = null;
            state.activeMarket = null;
        }
    }
}
window.cerrarModal = cerrarModal;

document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') cerrarModal();
});
document.addEventListener('click', (e) => {
    if (e.target.id === 'modal-general') cerrarModal();
});

// Resize
window.addEventListener('resize', () => {
  const w = container.clientWidth;
  const h = container.clientHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  if (!controls.enableRotate) {
    camera.position.y = calcH();
    controls.update();
  }
});
